INSERT INTO public."GuideMilestone" VALUES ('cmooaqqbf000mygognxsi9xn3', 'cmolc84qt0000noogp0gr4sjj', 'QUETE_SERIE', 'Étape 1', NULL, '<p style="text-align: center;">Guide rédigé par l''équipe Ganymède.</p><img src="https://i.gyazo.com/0a5cd701d47079078cad5f59fe91e700.png" class="img-large"><p>Spécial remerciement à Abeille<strong>🐝.</strong></p>', 0, 'Introduction', NULL, '#10b981', 220, 0, false, '{}', 1, '2026-05-02 12:06:57.723', '2026-05-02 12:06:57.723');
INSERT INTO public."GuideMilestone" VALUES ('cmooaqqbp000nygogohrt0e2h', 'cmolc84qt0000noogp0gr4sjj', 'PREREQUIS', '👉 Étape bonus 👈', NULL, '<p style="text-align: center;"><span style="color: rgb(250, 0, 0);">Bienvenue !</span></p><p><span style="color: rgb(255, 255, 255);">Ce guide vise à vous faire accomplir </span><span style="color: rgb(255, 255, 0);">100% des donjons</span><span style="color: rgb(255, 255, 255);">, compléter </span><span style="color: rgb(255, 255, 0);">100% des quêtes de zone </span><span style="color: rgb(255, 255, 255);">et de l''</span><span style="color: rgb(255, 255, 0);">histoire principale</span><span style="color: rgb(255, 255, 255);">, obtenir </span><span style="color: rgb(255, 255, 0);">100% des Dofus</span><span style="color: rgb(255, 255, 255);">.</span></p><p><span style="color: rgb(255, 255, 255);">Tout est ordonné de manière à vous proposer un </span><span style="color: rgb(255, 255, 0);">leveling organique</span>.</p><p>Tout contenu <span style="color: rgb(255, 255, 0);">non nécessaire</span><span style="color: rgb(255, 255, 255);"> à la </span><span style="color: rgb(255, 255, 0);">réalisation d''un Dofus</span> ou d''une <span style="color: rgb(255, 255, 0);">quête principale</span> sera marqué comme (<span style="color: rgb(170, 71, 188);">optionnel</span>).</p><p><span style="color: rgb(255, 255, 255);">Pour chaque </span><span style="color: rgb(255, 255, 0);">donjon</span><span style="color: rgb(255, 255, 255);">, vous serez informé des séries de quêtes liées à compléter en parallèle afin d''</span><span style="color: rgb(255, 255, 0);">optimiser vos récompenses</span><span style="color: rgb(255, 255, 255);">.</span></p><p>Cette version comprend des <span style="color: rgb(5, 160, 69);"><strong>👉 Étape bonus 👈 </strong></span><span style="color: rgb(255, 255, 255);">dont le but est de vous aider à </span><span style="color: rgb(255, 255, 0);">améliorer votre équipement</span><span style="color: rgb(255, 255, 255);"> ou </span><span style="color: rgb(255, 255, 0);">progresser dans votre métier de récolte 200</span><span style="color: rgb(255, 255, 255);">.</span></p><p><span style="color: rgb(255, 255, 255);">Ces étapes ne vous </span><span style="color: rgb(255, 255, 0);">obligent pas</span><span style="color: rgb(255, 255, 255);"> à le</span><span style="color: rgb(255, 255, 0);"> faire de suite</span><span style="color: rgb(255, 255, 255);">, vous êtes libre d''</span><span style="color: rgb(255, 255, 0);">améliorer votre équipement</span> ou <span style="color: rgb(255, 255, 0);">monter </span>votre <span style="color: rgb(255, 255, 0);">métier </span>plus tard.</p><p><span style="color: rgb(255, 255, 255);">Diverses </span><span style="color: rgb(255, 255, 0);">mécaniques du jeux</span><span style="color: rgb(255, 255, 255);"> seront </span><span style="color: rgb(255, 255, 0);">expliquées</span><span style="color: rgb(255, 255, 255);">.</span></p>', 0, 'Introduction', NULL, '#a855f7', 440, 0, true, '{}', 2, '2026-05-02 12:06:57.733', '2026-05-02 12:06:57.733');
INSERT INTO public."GuideMilestone" VALUES ('cmooaqqbx000oygogksez0mde', 'cmolc84qt0000noogp0gr4sjj', 'DONJON', 'Incarnam Astrub', NULL, NULL, 1, '[GP1] Incarnam Astrub', NULL, '#8b5cf6', 660, 0, false, '{}', 3, '2026-05-02 12:06:57.741', '2026-05-02 12:06:57.741');
INSERT INTO public."GuideMilestone" VALUES ('cmooaqqce000qygogrkbyl88m', 'cmolc84qt0000noogp0gr4sjj', 'DOFUS', 'Incarnam et début Krosmoz.', NULL, '<p><span style="color: rgb(250, 0, 0);">Objectifs :</span> Incarnam et début Krosmoz.</p><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p><span style="color: rgb(255, 255, 0);">Commencez </span>le guide <span data-type="guide-step" class="guide-step" guideid="2" stepid="0" stepnumber="1" guidename="[GP1] Incarnam Astrub" label="[GP1] Incarnam &amp; Astrub" baseurl="https://ganymede-dofus.com"><img src="https://ganymede-dofus.com/images/texteditor/guides.png" alt="GuideStep">[GP1] Incarnam &amp; Astrub</span> jusqu''à l''<span style="color: rgb(255, 255, 0);">étape 251️⃣</span> incluse.</p></div></li></ul><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p><span style="color: rgb(255, 255, 0);">Commencez </span>le guide <span data-type="guide-step" class="guide-step" guideid="374" stepid="0" stepnumber="1" guidename="[GP2] Krosmoz" label="[GP2] Krosmoz" baseurl="https://ganymede-dofus.com"><img src="https://ganymede-dofus.com/images/texteditor/guides.png" alt="GuideStep">[GP2] Krosmoz</span><span style="color: rgb(255, 255, 0);"> </span>jusqu''à l''<span style="color: rgb(255, 255, 0);">étape 8</span> incluse.</p></div></li></ul><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p><span style="color: rgb(255, 255, 0);">Reprenez&nbsp;</span>le guide <span data-type="guide-step" class="guide-step" guideid="2" stepid="0" stepnumber="1" guidename="[GP1] Incarnam Astrub" label="[GP1] Incarnam &amp; Astrub" baseurl="https://ganymede-dofus.com"><img src="https://ganymede-dofus.com/images/texteditor/guides.png" alt="GuideStep">[GP1] Incarnam &amp; Astrub</span>&nbsp;de l''<span style="color: rgb(255, 255, 0);">étape 25</span>2️⃣ jusqu''à l''<span style="color: rgb(255, 255, 0);">étape 583️⃣4️⃣</span> incluse <span style="color: rgb(250, 0, 0);">SANS </span>cliquer sur le <span style="color: rgb(98, 172, 255);">Portail vers Astrub</span>.</p></div></li></ul><p><span style="color: rgb(5, 160, 69);">Astuces :</span></p><p>1️⃣ Cela veut dire que vous <span style="color: rgb(255, 255, 0);">faites </span>l''<span style="color: rgb(255, 255, 0);">étape 25</span> du guide <span style="color: rgb(255, 255, 0);">SANS aller</span> à l''<span style="color: rgb(255, 255, 0);">étape 26</span>.</p><p>Puis vous <span style="color: rgb(255, 255, 0);">reprendrez </span><span style="color: rgb(255, 255, 255);">le </span><span data-type="guide-step" class="guide-step" guideid="2747" stepid="0" stepnumber="1" guidename="[GP0] Guide complet Ganymède (NEW)" label="[GP0] Guide complet Ganymède" baseurl="https://ganymede-app.com"><img src="https://ganymede-app.com/images/texteditor/guides.png" alt="GuideStep">[GP0] Guide complet Ganymède</span> (ce guide) pour faire la suite.</p><p>2️⃣ A l''<span style="color: rgb(255, 255, 0);">étape 25</span>, vous <span style="color: rgb(255, 255, 0);">suivez directement</span> le <span style="color: rgb(255, 255, 0);">chemin </span>en bas de l''étape car vous l''avez déjà faite.</p><p>3️⃣ Vers l''<span style="color: rgb(255, 255, 0);">étape 31</span>, vous débloquez l''<span style="color: rgb(255, 255, 0);">autopilote</span> qui vous permet avec un <span style="color: rgb(255, 255, 0);">double Clic Gauche</span> de <span style="color: rgb(255, 255, 0);">vous rendre</span> sur la <span style="color: rgb(255, 255, 0);">case ciblé</span> depuis votre <span style="color: rgb(255, 255, 0);">minimap</span>.</p><p>4️⃣ A l''<span style="color: rgb(255, 255, 0);">étape 50</span>, <span style="color: rgb(255, 255, 0);">essayez </span>de faire un <span style="color: rgb(255, 255, 0);">maximum </span>de <span style="color: rgb(255, 255, 0);">succès </span>dans la <span data-type="custom-tag" data-id="90" class="tag-dungeon" id="77" type="dungeon" name="Crypte de Kardorim" imageurl="https://ganymede-app.com/images/icon_dungeon.png" dofusdbid="90"><img src="https://ganymede-app.com/images/icon_dungeon.png" alt="dungeon"><span>Crypte de Kardorim</span></span>.</p><p>Globalement faites toujours un <span style="color: rgb(255, 255, 0);">maximum </span>de <span style="color: rgb(255, 255, 0);">challenges </span>dans les <span style="color: rgb(98, 172, 255);">salles des donjons</span> et de <span style="color: rgb(255, 255, 0);">succès </span>dans la <span style="color: rgb(98, 172, 255);">salle du boss</span>.</p>', 1, '[GP1] Incarnam Astrub', NULL, '#f59e0b', 0, 0, false, '{}', 4, '2026-05-02 12:06:57.758', '2026-05-02 12:06:57.758');
INSERT INTO public."GuideMilestone" VALUES ('cmooaqqd4000uygog8l39vc6e', 'cmolc84qt0000noogp0gr4sjj', 'PREREQUIS', '👉 Étape bonus 👈', NULL, '<p style="text-align: center;"><span style="color: rgb(5, 160, 69);"><strong>👉 Étape bonus 👈</strong></span></p><p style="text-align: center;">🌽 Paysan/Alchimiste 0 à 10 🌽</p><p style="text-align: center;">🥩 Chasseur 0 à 10 🥩</p><p style="text-align: center;">☎️ Q&amp;A ☎️</p><p style="text-align: left;"><span style="color: rgb(255, 255, 0);">Choisissez </span>de <span style="color: rgb(255, 255, 0);">monter </span>soit le <span style="color: rgb(255, 255, 0);">métier paysan1️⃣</span> soit le <span style="color: rgb(255, 255, 0);">métier alchimiste2️⃣</span> (voir ☎️ Q&amp;A ☎️ plus bas).</p><p style="text-align: left;">En étant sur <span style="color: rgb(98, 172, 255);">Incarnam</span>, commencez à <span style="color: rgb(255, 255, 0);">monter </span>votre <span style="color: rgb(255, 255, 0);">métier </span>jusqu''au <span style="color: rgb(255, 255, 0);">niveau 10</span>.</p><p style="text-align: left;"><span style="color: rgb(255, 255, 0);">Récupérez </span>du <span data-type="custom-tag" data-id="289" class="tag-item" id="75" type="item" name="Blé" imageurl="https://api.dofusdb.fr/img/items/34009.png" dofusdbid="289"><img src="https://api.dofusdb.fr/img/items/34009.png" alt="item"><span>Blé</span></span> et/ou <span style="color: rgb(255, 255, 0);">fabriquez </span>du <span data-type="custom-tag" data-id="468" class="tag-item" id="227" type="item" name="Pain d''Incarnam" imageurl="https://api.dofusdb.fr/img/items/33013.png" dofusdbid="468"><img src="https://api.dofusdb.fr/img/items/33013.png" alt="item"><span>Pain d''Incarnam</span></span> si vous êtes <span style="color: rgb(255, 255, 0);">paysan</span>.</p><p style="text-align: left;"><span style="color: rgb(255, 255, 0);">Récupérez </span>des <span data-type="custom-tag" data-id="421" class="tag-item" id="186" type="item" name="Ortie" imageurl="https://api.dofusdb.fr/img/items/36642.png" dofusdbid="421"><img src="https://api.dofusdb.fr/img/items/36642.png" alt="item"><span>Ortie</span></span> et/ou <span style="color: rgb(255, 255, 0);">fabriquez </span>des <span data-type="custom-tag" data-id="1182" class="tag-item" id="582" type="item" name="Potion de Mini Soin" imageurl="https://api.dofusdb.fr/img/items/12016.png" dofusdbid="1182"><img src="https://api.dofusdb.fr/img/items/12016.png" alt="item"><span>Potion de Mini Soin</span></span> si vous êtes <span style="color: rgb(255, 255, 0);">alchimiste</span>.</p><p style="text-align: center;">🥩 Chasseur 0 à 10 🥩</p><p style="text-align: left;">Pour monter le métier <span style="color: rgb(255, 255, 0);">chasseur niveau 10</span>, prévoyez 77 <span data-type="custom-tag" data-id="16663" class="tag-item" id="9532" type="item" name="Viande Intangible" imageurl="https://api.dofusdb.fr/img/items/63407.png" dofusdbid="16663"><img src="https://api.dofusdb.fr/img/items/63407.png" alt="item"><span>Viande Intangible</span></span>3️⃣.</p><p><span style="color: rgb(255, 255, 0);">Vérifiez </span>la <span style="color: rgb(255, 255, 0);">quantité </span>déjà <span style="color: rgb(255, 255, 0);">en votre possession</span> et allez <span style="color: rgb(255, 255, 0);">drop </span>ou <span style="color: rgb(255, 255, 0);">acheter </span>le reste.</p><p>Ensuite <span style="color: rgb(255, 255, 0);">fabriquez </span>des <span data-type="custom-tag" data-id="16670" class="tag-item" id="9536" type="item" name="Bouillon de Chair" imageurl="https://api.dofusdb.fr/img/items/69741.png" dofusdbid="16670"><img src="https://api.dofusdb.fr/img/items/69741.png" alt="item"><span>Bouillon de Chair</span></span> dans l''<span style="color: rgb(98, 172, 255);">Atelier des chasseurs</span> en [-1,-2].</p><p style="text-align: center;">☎️ Q&amp;A ☎️</p><p><span style="color: rgb(5, 160, 69);">Q : </span>Pourquoi monter les métier de <span style="color: rgb(255, 255, 0);">paysan </span><span style="color: rgb(255, 255, 255);">ou d''</span><span style="color: rgb(255, 255, 0);">alchimiste </span>au cours de ce guide ?</p><p><span style="color: rgb(5, 160, 69);">A : </span><span style="color: rgb(255, 255, 255);">Vous aurez besoin d''</span><span style="color: rgb(255, 255, 0);">un métier niveau 50</span><span style="color: rgb(255, 255, 255);">, comme prérequis d''une quête du </span><span data-type="guide-step" class="guide-step" guideid="66" stepid="0" stepnumber="1" guidename="[GP19] DOFUS EMERAUDE" label="[GP19] DOFUS EMERAUDE" baseurl="https://ganymede-app.com"><img src="https://ganymede-app.com/images/texteditor/guides.png" alt="GuideStep">[GP19] DOFUS EMERAUDE</span>.</p><p><span style="color: rgb(255, 255, 255);">Puis, d''</span><span style="color: rgb(255, 255, 0);">un métier niveau 200</span><span style="color: rgb(255, 255, 255);">, comme prérequis d''une quête du guide </span><span data-type="guide-step" class="guide-step" guideid="433" stepid="0" stepnumber="1" guidename="[GP54] Enutrosor 3" label=" [GP54] Enutrosor 3" baseurl="https://ganymede-dofus.com"><img src="https://ganymede-dofus.com/images/texteditor/guides.png" alt="GuideStep"> [GP54] Enutrosor 3</span> et du <span data-type="guide-step" class="guide-step" guideid="1729" stepid="0" stepnumber="1" guidename="[GP56] DOFUS ABYSSAL" label="[GP56] DOFUS ABYSSAL" baseurl="https://ganymede-app.com"><img src="https://ganymede-app.com/images/texteditor/guides.png" alt="GuideStep">[GP56] DOFUS ABYSSAL</span>.</p><p>Et enfin d''être <span style="color: rgb(255, 255, 0);">Paysan </span><span style="color: rgb(255, 255, 255);">ou </span><span style="color: rgb(255, 255, 0);">Alchimiste</span> de<span style="color: rgb(255, 255, 0);"> niveau 200</span> pour une quête du <span data-type="guide-step" class="guide-step" guideid="704" stepid="0" stepnumber="1" guidename="[GP67] Dofus Vulbis" label=" [GP67] Dofus Vulbis" baseurl="https://ganymede-dofus.com"><img src="https://ganymede-dofus.com/images/texteditor/guides.png" alt="GuideStep"> [GP67] Dofus Vulbis</span>.</p><p><span style="color: rgb(5, 160, 69);">Astuces :</span></p><p>1️⃣ Le <span style="color: rgb(255, 255, 0);">métier paysan</span> à l''avantage de nécessité <span style="color: rgb(255, 255, 0);">peu </span>de <span style="color: rgb(255, 255, 0);">déplacement </span>en moyenne mais il y a <span style="color: rgb(255, 255, 0);">beaucoup </span>de <span style="color: rgb(255, 255, 0);">concurrence</span>.</p><p>Si vous voulez monter le <span style="color: rgb(255, 255, 0);">métier chasseur</span>, celui-ci <span style="color: rgb(255, 255, 0);">nécessite </span>des <span style="color: rgb(255, 255, 0);">ressources </span>du <span style="color: rgb(255, 255, 0);">métier paysan</span>.</p><p style="text-align: left;">2️⃣ Le <span style="color: rgb(255, 255, 0);">métier alchimiste</span> à l''avantage d''avoir <span style="color: rgb(255, 255, 0);">moins de concurrence</span> mais nécessite <span style="color: rgb(255, 255, 0);">plus </span>de <span style="color: rgb(255, 255, 0);">déplacements</span>.</p><p style="text-align: left;">1️⃣2️⃣ Sur l''app, il y a un <span style="color: rgb(255, 255, 0);">outil Carte</span> qui renvoie à la carte du site suivant : <a target="_blank" rel="noopener noreferrer nofollow" href="https://dofusdb.fr/fr/tools/map">https://dofusdb.fr/fr/tools/map</a>.</p><p style="text-align: left;">Cet outil<span style="color: rgb(255, 255, 255);"> indispensable permet de</span><span style="color: rgb(255, 255, 0);"> situer les ressources</span><span style="color: rgb(255, 255, 255);"> sur la </span><span style="color: rgb(255, 255, 0);">carte du monde</span><span style="color: rgb(255, 255, 255);">.</span></p><p>3️⃣ <span style="color: rgb(255, 255, 0);">Equipez </span>la <span data-type="custom-tag" data-id="30828" class="tag-item" id="19982" type="item" name="Bounihimée" imageurl="https://api.dofusdb.fr/img/items/6757.png" dofusdbid="30828"><img src="https://api.dofusdb.fr/img/items/6757.png" alt="item"><span>Bounihimée</span></span> pour <span style="color: rgb(255, 255, 0);">drop </span>des <span style="color: rgb(255, 255, 0);">viandes</span>.</p><p>Pour info, la <span data-type="custom-tag" data-id="30828" class="tag-item" id="19982" type="item" name="Bounihimée" imageurl="https://api.dofusdb.fr/img/items/6757.png" dofusdbid="30828"><img src="https://api.dofusdb.fr/img/items/6757.png" alt="item"><span>Bounihimée</span></span> possède l''effet "<span style="color: rgb(255, 255, 0);">Arme de chasse</span>" qui permet d''obtenir des viandes.</p><p>Ces <span style="color: rgb(255, 255, 0);">viandes </span>sont <span style="color: rgb(255, 255, 0);">nécessaires </span>pour <span style="color: rgb(255, 255, 0);">monter </span>le<span style="color: rgb(170, 71, 188);"> </span><span style="color: rgb(255, 255, 0);">métier chasseur</span>.</p><p>Ce métier n''est <span style="color: rgb(255, 255, 0);">pas obligatoire</span> mais <span style="color: rgb(255, 255, 0);">permet </span>d''avoir du <span style="color: rgb(255, 255, 0);">drop en plus</span> sur <span style="color: rgb(255, 255, 0);">chaque combat</span> du jeu.</p>', 19, '[GP19] DOFUS EMERAUDE', NULL, '#a855f7', 220, 160, true, '{}', 5, '2026-05-02 12:06:57.784', '2026-05-02 12:06:57.784');
INSERT INTO public."GuideMilestone" VALUES ('cmooaqqdz000zygogpk39hohk', 'cmolc84qt0000noogp0gr4sjj', 'QUETE_SERIE', 'Krosmoz et Almanax.', NULL, '<p><span style="color: rgb(250, 0, 0);">Objectifs :</span> Krosmoz et Almanax.</p><p>Prenez le <span style="color: rgb(98, 172, 255);">Portail vers Astrub</span> en [4,-3].</p><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p><span style="color: rgb(255, 255, 0);">Débloquez </span>le <span style="color: rgb(98, 172, 255);">Zaap </span>de la<span style="color: rgb(98, 172, 255);"> Cité d''Astrub</span>.</p></div></li></ul><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p>(<span style="color: rgb(170, 71, 188);">Optionnel</span>) <span style="color: rgb(255, 255, 0);">Lancez</span> la quête <span data-type="custom-tag" data-id="953" class="tag-quest" id="679" type="quest" name="L''Almanax du Mage Ax" imageurl="https://ganymede-app.com/images/icon_quest.png" dofusdbid="953"><img src="https://ganymede-app.com/images/icon_quest.png" alt="quest"><span>L''Almanax du Mage Ax</span></span> en [3,-21].</p></div></li></ul><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p><span style="color: rgb(255, 255, 0);">Débloquez </span>le <span style="color: rgb(98, 172, 255);">Zaap </span>de la<span style="color: rgb(98, 172, 255);"> Plaine des Porkass</span><span style="color: rgb(255, 255, 255);"> en [-5,-23].</span></p></div></li></ul><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p><span style="color: rgb(255, 255, 0);">Reprenez </span><span style="color: rgb(255, 255, 255);">le guide </span><span data-type="guide-step" class="guide-step" guideid="374" stepid="0" stepnumber="1" guidename="[GP2] Krosmoz" label="[GP2] Krosmoz" baseurl="https://ganymede-dofus.com"><img src="https://ganymede-dofus.com/images/texteditor/guides.png" alt="GuideStep">[GP2] Krosmoz</span>1️⃣<span style="color: rgb(255, 255, 255);"> </span>de l''<span style="color: rgb(255, 255, 0);">étape 9</span> à l''<span style="color: rgb(255, 255, 0);">étape 10 </span>incluse.</p></div></li></ul><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p><span style="color: rgb(255, 255, 0);">Terminez </span>la quête <span data-type="custom-tag" data-id="953" class="tag-quest" id="679" type="quest" name="L''Almanax du Mage Ax" imageurl="https://ganymede-app.com/images/icon_quest.png" dofusdbid="953"><img src="https://ganymede-app.com/images/icon_quest.png" alt="quest"><span>L''Almanax du Mage Ax</span></span> dans le <span style="color: rgb(98, 172, 255);">Temple de l''Almanax</span>.</p></div></li></ul><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p><span style="color: rgb(255, 255, 0);">Lisez </span>le guide <span data-type="guide-step" class="guide-step" guideid="484" stepid="0" stepnumber="1" guidename="[GP3] Dolmanax" label="[GP3] Dolmanax" baseurl="https://ganymede-dofus.com"><img src="https://ganymede-dofus.com/images/texteditor/guides.png" alt="GuideStep">[GP3] Dolmanax</span>2️⃣ pour en apprendre plus sur l''<span style="color: rgb(255, 255, 0);">Almanax</span>, car avec régularité, vous serez <span style="color: rgb(255, 255, 0);">récompensé </span>avec le <span data-type="custom-tag" data-id="13344" class="tag-item" id="6750" type="item" name="Dolmanax" imageurl="https://api.dofusdb.fr/img/items/23018.png" dofusdbid="13344"><img src="https://api.dofusdb.fr/img/items/23018.png" alt="item"><span>Dolmanax</span></span>.</p></div></li></ul><p><span style="color: rgb(5, 160, 69);">Astuces :</span></p><p>1️⃣ Dans ce guide à l''<span style="color: rgb(255, 255, 0);">étape 10</span>, vous lancez la quête <span data-type="custom-tag" data-id="1198" class="tag-quest" id="918" type="quest" name="Du rire en barre" imageurl="https://ganymede-dofus.com/images/icon_quest.png" dofusdbid="1198"><img src="https://ganymede-dofus.com/images/icon_quest.png" alt="quest"><span>Du rire en barre</span></span> qui demande de <span style="color: rgb(255, 255, 0);">récolter </span>des <span style="color: rgb(255, 255, 0);">rabmablagues</span>.</p><p>Etant une <span style="color: rgb(255, 255, 0);">quête longue</span>, <span style="color: rgb(255, 255, 255);">la </span><span style="color: rgb(255, 255, 0);">lancer </span><span style="color: rgb(255, 255, 255);">au plus </span><span style="color: rgb(255, 255, 0);">tôt </span><span style="color: rgb(255, 255, 255);">dans votre aventure vous </span><span style="color: rgb(255, 255, 0);">permet </span><span style="color: rgb(255, 255, 255);">de les </span><span style="color: rgb(255, 255, 0);">réunir </span><span style="color: rgb(255, 255, 255);">avec le temps </span><span style="color: rgb(255, 255, 0);">sans vous en soucier</span><span style="color: rgb(255, 255, 255);">.</span></p><p>2️⃣ Le <span style="color: rgb(98, 172, 255);">Temple de l''Almanax</span><span style="color: rgb(255, 255, 255);"> est le</span> point de rendez-vous de l''<span style="color: rgb(255, 255, 0);">Almanax</span>, une <span style="color: rgb(255, 255, 0);">mécanique du jeu</span> qui vous <span style="color: rgb(255, 255, 0);">récompense </span>pour vos <span style="color: rgb(255, 255, 0);">connexions quotidiennes</span>.</p><p>Dans le <span style="color: rgb(255, 255, 0);">calendrier </span>(touche "<span style="color: rgb(255, 255, 0);">x</span>"), vous pouvez voir l''<span style="color: rgb(255, 255, 0);">offrande du jour</span> ainsi que <span style="color: rgb(255, 255, 0);">celles </span>des <span style="color: rgb(255, 255, 0);">prochains jours</span>.</p><p>Il est normal qu''à ce stade de l''aventure vous ne puissiez pas encore faire d''offrande.</p>', 2, '[GP2] Krosmoz', NULL, '#10b981', 440, 160, false, '{}', 6, '2026-05-02 12:06:57.815', '2026-05-02 12:06:57.815');
INSERT INTO public."GuideMilestone" VALUES ('cmooaqqef0012ygogpu0vqatb', 'cmolc84qt0000noogp0gr4sjj', 'PREREQUIS', '👉 Étape bonus 👈', NULL, '<p style="text-align: center;"><span style="color: rgb(5, 160, 69);"><strong>👉 Étape bonus 👈</strong></span><br>🗡️ Mise à jour de l''équipement 🗡️</p><p>Dans la <span style="color: rgb(98, 172, 255);">Cité d''Astrub</span>, tuez des <span style="color: rgb(255, 255, 0);">Pious </span>pour <span style="color: rgb(255, 255, 0);">drop</span> la <span style="color: rgb(255, 255, 0);">Panoplie du Piou</span> complète correspondante à <span style="color: rgb(255, 255, 0);">votre élément</span>.</p><p>Pensez à faire des <span style="color: rgb(255, 255, 0);">challenges </span>en mode<span style="color: rgb(255, 255, 0);"> drop </span><span style="color: rgb(255, 255, 255);">pour augmenter vos chances.</span></p><p>Profitez en pour faire le <span style="color: rgb(255, 255, 0);">succès monstre </span>des <span style="color: rgb(255, 255, 0);">Pious</span><span style="color: rgb(255, 255, 255);">.</span></p><p>Vous pouvez aussi obtenir un <span style="color: rgb(255, 255, 0);">familier Pioute1️⃣</span> <span style="color: rgb(255, 255, 255);">en échangeant 100 </span><span data-type="custom-tag" data-id="287" class="tag-item" id="73" type="item" name="Graine de Sésame" imageurl="https://api.dofusdb.fr/img/items/58003.png" dofusdbid="287"><img src="https://api.dofusdb.fr/img/items/58003.png" alt="item"><span>Graine de Sésame</span></span> et<span style="color: rgb(255, 255, 255);"> :</span></p><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p>50 <span data-type="custom-tag" data-id="6897" class="tag-item" id="1951" type="item" name="Plume de Piou Bleu" imageurl="https://api.dofusdb.fr/img/items/53114.png" dofusdbid="6897"><img src="https://api.dofusdb.fr/img/items/53114.png" alt="item"><span>Plume de Piou Bleu</span></span> en [9,-28] pour la <span data-type="custom-tag" data-id="7708" class="tag-item" id="2481" type="item" name="Pioute bleu" imageurl="https://api.dofusdb.fr/img/items/18019.png" dofusdbid="7708"><img src="https://api.dofusdb.fr/img/items/18019.png" alt="item"><span>Pioute bleu</span></span> (+120 <span style="color: rgb(98, 172, 255);">chance</span>, +40 dommages critiques)</p></div></li><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p>50 <span data-type="custom-tag" data-id="6900" class="tag-item" id="1954" type="item" name="Plume de Piou Rouge" imageurl="https://api.dofusdb.fr/img/items/53117.png" dofusdbid="6900"><img src="https://api.dofusdb.fr/img/items/53117.png" alt="item"><span>Plume de Piou Rouge</span></span> en [-3,-13] pour la <span data-type="custom-tag" data-id="7711" class="tag-item" id="2484" type="item" name="Pioute rouge" imageurl="https://api.dofusdb.fr/img/items/18025.png" dofusdbid="7711"><img src="https://api.dofusdb.fr/img/items/18025.png" alt="item"><span>Pioute rouge</span></span> (+120 <span style="color: rgb(235, 65, 101);">intelligence</span>, +40 dommages critiques)</p></div></li><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p>50 <span data-type="custom-tag" data-id="6902" class="tag-item" id="1955" type="item" name="Plume de Piou Jaune" imageurl="https://api.dofusdb.fr/img/items/53118.png" dofusdbid="6902"><img src="https://api.dofusdb.fr/img/items/53118.png" alt="item"><span>Plume de Piou Jaune</span></span> en [4,-22] pour la <span data-type="custom-tag" data-id="7709" class="tag-item" id="2482" type="item" name="Pioute jaune" imageurl="https://api.dofusdb.fr/img/items/18023.png" dofusdbid="7709"><img src="https://api.dofusdb.fr/img/items/18023.png" alt="item"><span>Pioute jaune</span></span> (+120 <span style="color: rgb(131, 198, 131);">agilité</span>, +40 dommages critiques)</p></div></li><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p>50 <span data-type="custom-tag" data-id="6899" class="tag-item" id="1953" type="item" name="Plume de Piou Vert" imageurl="https://api.dofusdb.fr/img/items/53116.png" dofusdbid="6899"><img src="https://api.dofusdb.fr/img/items/53116.png" alt="item"><span>Plume de Piou Vert</span></span> en [11,-11] pour la <span data-type="custom-tag" data-id="7712" class="tag-item" id="2485" type="item" name="Pioute vert" imageurl="https://api.dofusdb.fr/img/items/18026.png" dofusdbid="7712"><img src="https://api.dofusdb.fr/img/items/18026.png" alt="item"><span>Pioute vert</span></span> (+120 <span style="color: rgb(115, 67, 9);">force </span>, +40 dommages critiques)</p></div></li><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p>50 <span data-type="custom-tag" data-id="6898" class="tag-item" id="1952" type="item" name="Plume de Piou Violet" imageurl="https://api.dofusdb.fr/img/items/53115.png" dofusdbid="6898"><img src="https://api.dofusdb.fr/img/items/53115.png" alt="item"><span>Plume de Piou Violet</span></span> en [10,-20] pour la <span data-type="custom-tag" data-id="7713" class="tag-item" id="2486" type="item" name="Pioute violet" imageurl="https://api.dofusdb.fr/img/items/18022.png" dofusdbid="7713"><img src="https://api.dofusdb.fr/img/items/18022.png" alt="item"><span>Pioute violet</span></span> (+70 <span style="color: rgb(255, 255, 0);">puissance</span>, +2 invocations)</p></div></li><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p>50 <span data-type="custom-tag" data-id="6903" class="tag-item" id="1956" type="item" name="Plume de Piou Rose" imageurl="https://api.dofusdb.fr/img/items/53119.png" dofusdbid="6903"><img src="https://api.dofusdb.fr/img/items/53119.png" alt="item"><span>Plume de Piou Rose</span></span> en [5,-17] pour la <span data-type="custom-tag" data-id="7710" class="tag-item" id="2483" type="item" name="Pioute rose" imageurl="https://api.dofusdb.fr/img/items/18024.png" dofusdbid="7710"><img src="https://api.dofusdb.fr/img/items/18024.png" alt="item"><span>Pioute rose</span></span> (+70 <span style="color: rgb(255, 255, 0);">puissance</span>, +2 Portée)</p></div></li></ul><p><span style="color: rgb(5, 160, 69);">Astuces :</span></p><p><span style="color: rgb(255, 255, 255);">1️⃣ Il faut </span><span style="color: rgb(255, 255, 0);">nourrir </span><span style="color: rgb(255, 255, 255);">votre </span><span style="color: rgb(255, 255, 0);">familier </span><span style="color: rgb(255, 255, 255);">pour le</span><span style="color: rgb(255, 255, 0);"> monter en niveau</span><span style="color: rgb(255, 255, 255);"> et ainsi </span><span style="color: rgb(255, 255, 0);">obtenir </span><span style="color: rgb(255, 255, 255);">de</span><span style="color: rgb(255, 255, 0);"> plus en plus </span><span style="color: rgb(255, 255, 255);">de </span><span style="color: rgb(255, 255, 0);">statistique</span><span style="color: rgb(255, 255, 255);">.</span></p><p><span style="color: rgb(255, 255, 255);">Pour le </span><span style="color: rgb(255, 255, 0);">nourrir</span><span style="color: rgb(255, 255, 255);">, faites </span><span style="color: rgb(255, 255, 0);">clic droit</span><span style="color: rgb(255, 255, 255);"> puis </span><span style="color: rgb(255, 255, 0);">nourrir </span><span style="color: rgb(255, 255, 255);">et </span><span style="color: rgb(255, 255, 0);">glisser </span><span style="color: rgb(255, 255, 255);">des </span><span style="color: rgb(255, 255, 0);">ressources</span><span style="color: rgb(255, 255, 255);">, </span><span style="color: rgb(255, 255, 0);">runes </span><span style="color: rgb(255, 255, 255);">de </span><span style="color: rgb(255, 255, 0);">forgemagies </span><span style="color: rgb(255, 255, 255);">ou des </span><span data-type="custom-tag" data-id="20125" class="tag-item" id="12496" type="item" name="Croquette enrichie" imageurl="https://api.dofusdb.fr/img/items/15528.png" dofusdbid="20125"><img src="https://api.dofusdb.fr/img/items/15528.png" alt="item"><span>Croquette enrichie</span></span>.</p><p><span style="color: rgb(255, 255, 0);">Briser des équipements </span><span style="color: rgb(255, 255, 255);">dans un </span><span style="color: rgb(255, 255, 0);">concasseur </span><span style="color: rgb(255, 255, 255);">vous donne des </span><span style="color: rgb(255, 255, 0);">runes</span><span style="color: rgb(255, 255, 255);"> de </span><span style="color: rgb(255, 255, 0);">forgemagies</span><span style="color: rgb(255, 255, 255);">.</span></p><p><span style="color: rgb(255, 255, 255);">Vous trouverez le </span><span style="color: rgb(255, 255, 0);">concasseur </span><span style="color: rgb(255, 255, 255);">le plus proche dans l''</span><span style="color: rgb(98, 172, 255);">Atelier des Forgemages</span><span style="color: rgb(255, 255, 255);"> en</span><span style="color: rgb(255, 255, 0);"> </span>[-5,-13].</p>', 0, 'Introduction', NULL, '#a855f7', 660, 160, true, '{}', 7, '2026-05-02 12:06:57.831', '2026-05-02 12:06:57.831');
INSERT INTO public."GuideMilestone" VALUES ('cmooaqqeo0013ygogmg0u9wsx', 'cmolc84qt0000noogp0gr4sjj', 'PREREQUIS', '👉 Étape bonus 👈', NULL, '<p style="text-align: center;"><span style="color: rgb(5, 160, 69);"><strong>👉 Étape bonus 👈</strong></span></p><p style="text-align: center;">🥩 Chasseur 10 à 20 🥩</p><p style="text-align: left;">Pour monter le métier <span style="color: rgb(255, 255, 0);">chasseur niveau 20</span>, prévoyez 244 <span data-type="custom-tag" data-id="17123" class="tag-item" id="9959" type="item" name="Viande Hachée" imageurl="https://api.dofusdb.fr/img/items/175008.png" dofusdbid="17123"><img src="https://api.dofusdb.fr/img/items/175008.png" alt="item"><span>Viande Hachée</span></span> obtenable sur les <span style="color: rgb(255, 255, 0);">Pious1️⃣</span>.</p><p><span style="color: rgb(255, 255, 0);">Vérifiez </span>la <span style="color: rgb(255, 255, 0);">quantité </span>déjà <span style="color: rgb(255, 255, 0);">en votre possession</span> et allez <span style="color: rgb(255, 255, 0);">drop </span>ou <span style="color: rgb(255, 255, 0);">acheter </span>le reste.</p><p>Ensuite <span style="color: rgb(255, 255, 0);">fabriquez </span>des <span data-type="custom-tag" data-id="17168" class="tag-item" id="10004" type="item" name="Boulette de Viande" imageurl="https://api.dofusdb.fr/img/items/69750.png" dofusdbid="17168"><img src="https://api.dofusdb.fr/img/items/69750.png" alt="item"><span>Boulette de Viande</span></span> dans l''<span style="color: rgb(98, 172, 255);">Atelier des chasseurs </span><span style="color: rgb(255, 255, 255);">en [5,-20].</span></p><p><span style="color: rgb(5, 160, 69);">Astuces :</span></p><p>1️⃣ Vous pouvez <span style="color: rgb(255, 255, 0);">vendre </span>les <span style="color: rgb(255, 255, 0);">équipements piou</span> obtenus dans l''<span style="color: rgb(255, 255, 0);">Hôtel de vente</span> (HDV) des <span style="color: rgb(255, 255, 0);">équipements</span>.</p><p>Sinon <span style="color: rgb(255, 255, 0);">brisez </span>les pour peut être <span style="color: rgb(255, 255, 0);">obtenir </span>vos <span style="color: rgb(255, 255, 0);">premières runes</span>.</p>', 0, 'Introduction', NULL, '#a855f7', 0, 160, true, '{}', 8, '2026-05-02 12:06:57.84', '2026-05-02 12:06:57.84');
INSERT INTO public."GuideMilestone" VALUES ('cmooaqqeu0014ygogcbuikfla', 'cmolc84qt0000noogp0gr4sjj', 'DONJON', 'Astrub.', NULL, '<p><span style="color: rgb(250, 0, 0);">Objectif :</span> Astrub.</p><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p style="text-align: left;"><span style="color: rgb(255, 255, 0);">Reprenez </span>le guide <span data-type="guide-step" class="guide-step" guideid="2" stepid="0" stepnumber="1" guidename="[GP1] Incarnam Astrub" label="[GP1] Incarnam &amp; Astrub" baseurl="https://ganymede-dofus.com"><img src="https://ganymede-dofus.com/images/texteditor/guides.png" alt="GuideStep">[GP1] Incarnam &amp; Astrub</span> de l''<span style="color: rgb(255, 255, 0);">étape 58&nbsp;</span>jusqu''à l''<span style="color: rgb(255, 255, 0);">étape 91</span> incluse.</p></div></li></ul><p style="text-align: center;"><span style="color: rgb(5, 160, 69);"><strong>👉 Partie bonus 👈</strong></span></p><p style="text-align: center;">🗡️ Mise à jour de l''équipement 🗡️</p><p><span style="color: rgb(255, 255, 255);">Si vous êtes d''élément </span><span style="color: rgb(98, 172, 255);">eau </span><span style="color: rgb(255, 255, 255);">ou </span><span style="color: rgb(131, 198, 131);">air</span><span style="color: rgb(255, 255, 255);">, pensez à </span><span style="color: rgb(255, 255, 0);">drop </span>ou <span style="color: rgb(255, 255, 0);">fabriquer</span><span style="color: rgb(255, 255, 255);"> la </span><span style="color: rgb(255, 255, 0);">Panoplie Mousse</span><span style="color: rgb(255, 255, 255);"> dans</span> <span style="color: rgb(255, 255, 255);">les </span><span style="color: rgb(98, 172, 255);">Calanques d''Astrub</span><span style="color: rgb(255, 255, 255);">.</span></p><p><span style="color: rgb(255, 255, 255);">N''hésitez pas à </span><span style="color: rgb(255, 255, 0);">refaire </span><span style="color: rgb(255, 255, 255);">le </span><span data-type="custom-tag" data-id="19" class="tag-dungeon" id="15" type="dungeon" name="Château Ensablé" imageurl="https://ganymede-dofus.com/images/icon_dungeon.png" dofusdbid="19"><img src="https://ganymede-dofus.com/images/icon_dungeon.png" alt="dungeon"><span>Château Ensablé</span></span> pour faire des succès.</p>', 1, '[GP1] Incarnam Astrub', NULL, '#8b5cf6', 220, 320, true, '{}', 9, '2026-05-02 12:06:57.846', '2026-05-02 12:06:57.846');
INSERT INTO public."GuideMilestone" VALUES ('cmooaqqf40016ygogyebhd3ol', 'cmolc84qt0000noogp0gr4sjj', 'PREREQUIS', '👉 Étape bonus 👈', NULL, '<p style="text-align: center;"><span style="color: rgb(5, 160, 69);"><strong>👉 Étape bonus 👈</strong></span></p><p style="text-align: center;">🥩 Chasseur 20 à 30 🥩</p><p style="text-align: center;">🌽Paysan/Alchimiste 10 à 20 🌽</p><p>Continuez de <span style="color: rgb(255, 255, 0);">monter </span>votre <span style="color: rgb(255, 255, 0);">métier de récolte </span>jusqu''au <span style="color: rgb(255, 255, 0);">niveau 20</span>.</p><p><span style="color: rgb(255, 255, 0);">Récupérez </span>du <span data-type="custom-tag" data-id="289" class="tag-item" id="75" type="item" name="Blé" imageurl="https://api.dofusdb.fr/img/items/34009.png" dofusdbid="289"><img src="https://api.dofusdb.fr/img/items/34009.png" alt="item"><span>Blé</span></span> et/ou <span style="color: rgb(255, 255, 0);">fabriquez </span>des <span data-type="custom-tag" data-id="468" class="tag-item" id="227" type="item" name="Pain d''Incarnam" imageurl="https://api.dofusdb.fr/img/items/33013.png" dofusdbid="468"><img src="https://api.dofusdb.fr/img/items/33013.png" alt="item"><span>Pain d''Incarnam</span></span> si vous êtes <span style="color: rgb(255, 255, 0);">paysan</span>.</p><p style="text-align: left;"><span style="color: rgb(255, 255, 0);">Récupérez </span>des <span data-type="custom-tag" data-id="421" class="tag-item" id="186" type="item" name="Ortie" imageurl="https://api.dofusdb.fr/img/items/36642.png" dofusdbid="421"><img src="https://api.dofusdb.fr/img/items/36642.png" alt="item"><span>Ortie</span></span> et/ou <span style="color: rgb(255, 255, 0);">fabriquez </span>des <span data-type="custom-tag" data-id="1182" class="tag-item" id="582" type="item" name="Potion de Mini Soin" imageurl="https://api.dofusdb.fr/img/items/12016.png" dofusdbid="1182"><img src="https://api.dofusdb.fr/img/items/12016.png" alt="item"><span>Potion de Mini Soin</span></span> si vous êtes <span style="color: rgb(255, 255, 0);">alchimiste</span>.</p><p style="text-align: center;">🥩 Chasseur 20 à 30 🥩</p><p>Pour monter le métier <span style="color: rgb(255, 255, 0);">chasseur niveau 30</span>, prévoyez :</p><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p>198 <span data-type="custom-tag" data-id="17124" class="tag-item" id="9960" type="item" name="Viande Faisandée" imageurl="https://api.dofusdb.fr/img/items/63348.png" dofusdbid="17124"><img src="https://api.dofusdb.fr/img/items/63348.png" alt="item"><span>Viande Faisandée</span></span>1️⃣</p></div></li><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p>198 <span data-type="custom-tag" data-id="289" class="tag-item" id="75" type="item" name="Blé" imageurl="https://api.dofusdb.fr/img/items/34009.png" dofusdbid="289"><img src="https://api.dofusdb.fr/img/items/34009.png" alt="item"><span>Blé</span></span></p></div></li></ul><p>Ensuite <span style="color: rgb(255, 255, 0);">fabriquez </span>des <span data-type="custom-tag" data-id="17169" class="tag-item" id="10005" type="item" name="Beignet Astrubien" imageurl="https://api.dofusdb.fr/img/items/69115.png" dofusdbid="17169"><img src="https://api.dofusdb.fr/img/items/69115.png" alt="item"><span>Beignet Astrubien</span></span> dans l''<span style="color: rgb(98, 172, 255);">Atelier des chasseurs</span> en [5,-20].</p><p><span style="color: rgb(5, 160, 69);">Astuces :</span></p><p>1️⃣ Dans l''<span style="color: rgb(255, 255, 0);">encyclopédie</span> (touche "<span style="color: rgb(255, 255, 0);">b</span>"), <span style="color: rgb(255, 255, 0);">recherchez </span>dans les <span style="color: rgb(255, 255, 0);">ressources </span>la <span data-type="custom-tag" data-id="17124" class="tag-item" id="9960" type="item" name="Viande Faisandée" imageurl="https://api.dofusdb.fr/img/items/63348.png" dofusdbid="17124"><img src="https://api.dofusdb.fr/img/items/63348.png" alt="item"><span>Viande Faisandée</span></span>.</p><p>Ensuite faites <span style="color: rgb(255, 255, 255);">un</span> <span style="color: rgb(255, 255, 0);">clic droit </span><span style="color: rgb(255, 255, 255);">sur celle-ci</span><span style="color: rgb(255, 255, 0);"> </span>puis <span style="color: rgb(255, 255, 0);">Bestiaire </span>pour voir sur<span style="color: rgb(255, 255, 0);"> quels monstres l''obtenir</span> ainsi que le <span style="color: rgb(255, 255, 0);">taux de drop</span>.</p>', 0, 'Introduction', NULL, '#a855f7', 440, 320, true, '{}', 10, '2026-05-02 12:06:57.856', '2026-05-02 12:06:57.856');
