INSERT INTO public."GuideMilestone" VALUES ('cmooaqqht001mygog1jzabnzk', 'cmolc84qt0000noogp0gr4sjj', 'DOFUS', 'Tour du Monde.', NULL, '<p><span style="color: rgb(250, 0, 0);">Objectif :</span> Tour du Monde.</p><div data-type="quest-block" class="quest-block" title="Donjon éducatif" questid="1947" questname="Donjon éducatif" status="in_progress"><p><span style="color: rgb(255, 255, 0);">Réalisez </span>l''<span data-type="custom-tag" data-id="138" class="tag-dungeon" id="120" type="dungeon" name="Akadémie des Gobs" imageurl="https://ganymede-dofus.com/images/icon_dungeon.png" dofusdbid="138"><img src="https://ganymede-dofus.com/images/icon_dungeon.png" alt="dungeon"><span>Akadémie des Gobs</span></span>1️⃣ en [-5,3] (<span style="color: rgb(98, 172, 255);">Zaap </span>du <span style="color: rgb(98, 172, 255);">Bord de la forêt maléfique</span>).</p></div><div data-type="quest-block" class="quest-block" title="Donjon éducatif" questid="1947" questname="Donjon éducatif" status="end"><p><span style="color: rgb(98, 172, 255);">Allez en</span> [1,-15] et parlez à <span style="color: rgb(255, 255, 0);">Emma Tompouce</span> pour finir <span data-type="custom-tag" data-id="2504" class="tag-quest" id="1947" type="quest" name="Donjon éducatif" imageurl="https://ganymede-dofus.com/images/icon_quest.png" dofusdbid="2504"><img src="https://ganymede-dofus.com/images/icon_quest.png" alt="quest"><span>Donjon éducatif</span></span>.</p></div><div data-type="quest-block" class="quest-block" title="Donjon douillet" questid="624" questname="Donjon douillet" status="start"><p><span style="color: rgb(255, 255, 0);">Continuez </span>de lui <span style="color: rgb(255, 255, 0);">parler </span>pour lancer <span data-type="custom-tag" data-id="898" class="tag-quest" id="624" type="quest" name="Donjon douillet" imageurl="https://ganymede-dofus.com/images/icon_quest.png" dofusdbid="898"><img src="https://ganymede-dofus.com/images/icon_quest.png" alt="quest"><span>Donjon douillet</span></span>.</p></div><p><span style="color: rgb(5, 160, 69);">Astuces :</span></p><p>1️⃣ Dans la <span style="color: rgb(98, 172, 255);">salle 1</span>, entrez dans le <span style="color: rgb(98, 172, 255);">casier </span>pour <span style="color: rgb(255, 255, 0);">prendre </span>le sort <span style="color: rgb(255, 255, 0);">Foudroiement de Grunob</span>.</p><p>Faites un <span style="color: rgb(255, 255, 0);">challenge </span>sur un <span data-type="custom-tag" data-id="6900" class="tag-monster" id="4469" type="monster" name="Gobichon" imageurl="https://api.dofusdb.fr/img/monsters/1180.png" dofusdbid="6900"><img src="https://api.dofusdb.fr/img/monsters/1180.png" alt="monster"><span>Gobichon</span></span>.</p>', 0, 'Introduction', NULL, '#f59e0b', 660, 640, false, '{}', 19, '2026-05-02 12:06:57.953', '2026-05-02 12:06:57.953');
INSERT INTO public."GuideMilestone" VALUES ('cmooaqqhz001nygog15wtcxbe', 'cmolc84qt0000noogp0gr4sjj', 'PREREQUIS', '👉 Étape bonus 👈', NULL, '<p style="text-align: center;"><span style="color: rgb(5, 160, 69);"><strong>👉 Étape bonus 👈</strong></span></p><p style="text-align: center;">🥩 Chasseur 40 à 50 🥩</p><p style="text-align: center;">🌽 Paysan/Alchimiste 20 à 30 🌽</p><p>Continuez de <span style="color: rgb(255, 255, 0);">monter </span>votre <span style="color: rgb(255, 255, 0);">métier </span>jusqu''au <span style="color: rgb(255, 255, 0);">niveau 30</span>.</p><p><span style="color: rgb(255, 255, 0);">Récupérez </span>de l''<span data-type="custom-tag" data-id="400" class="tag-item" id="168" type="item" name="Orge" imageurl="https://api.dofusdb.fr/img/items/34082.png" dofusdbid="400"><img src="https://api.dofusdb.fr/img/items/34082.png" alt="item"><span>Orge</span></span> et/ou <span style="color: rgb(255, 255, 0);">fabriquez </span>des <span data-type="custom-tag" data-id="528" class="tag-item" id="255" type="item" name="Carasau" imageurl="https://api.dofusdb.fr/img/items/33007.png" dofusdbid="528"><img src="https://api.dofusdb.fr/img/items/33007.png" alt="item"><span>Carasau</span></span> si vous êtes <span style="color: rgb(255, 255, 0);">paysan</span>.</p><p style="text-align: left;"><span style="color: rgb(255, 255, 0);">Récupérez </span>des <span data-type="custom-tag" data-id="428" class="tag-item" id="193" type="item" name="Sauge" imageurl="https://api.dofusdb.fr/img/items/36643.png" dofusdbid="428"><img src="https://api.dofusdb.fr/img/items/36643.png" alt="item"><span>Sauge</span></span> et/ou <span style="color: rgb(255, 255, 0);">fabriquez </span>des <span data-type="custom-tag" data-id="1183" class="tag-item" id="583" type="item" name="Potion de Mini Soin Supérieure" imageurl="https://api.dofusdb.fr/img/items/12038.png" dofusdbid="1183"><img src="https://api.dofusdb.fr/img/items/12038.png" alt="item"><span>Potion de Mini Soin Supérieure</span></span> si vous êtes <span style="color: rgb(255, 255, 0);">alchimiste</span>.</p><p style="text-align: center;">🥩 Chasseur 40 à 50 🥩</p><p style="text-align: left;">Pour monter le métier <span style="color: rgb(255, 255, 0);">chasseur niveau 50</span>, prévoyez :</p><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p style="text-align: left;">176 <span data-type="custom-tag" data-id="17128" class="tag-item" id="9964" type="item" name="Viande Minérale" imageurl="https://api.dofusdb.fr/img/items/63411.png" dofusdbid="17128"><img src="https://api.dofusdb.fr/img/items/63411.png" alt="item"><span>Viande Minérale</span></span>1️⃣</p></div></li><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p style="text-align: left;">176 <span data-type="custom-tag" data-id="400" class="tag-item" id="168" type="item" name="Orge" imageurl="https://api.dofusdb.fr/img/items/34082.png" dofusdbid="400"><img src="https://api.dofusdb.fr/img/items/34082.png" alt="item"><span>Orge</span></span></p></div></li><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p style="text-align: left;">176 <span data-type="custom-tag" data-id="1736" class="tag-item" id="846" type="item" name="Citron" imageurl="https://api.dofusdb.fr/img/items/46266.png" dofusdbid="1736"><img src="https://api.dofusdb.fr/img/items/46266.png" alt="item"><span>Citron</span></span> (ou 18 <span data-type="custom-tag" data-id="16822" class="tag-item" id="9687" type="item" name="Sachet de Citrons" imageurl="https://api.dofusdb.fr/img/items/180004.png" dofusdbid="16822"><img src="https://api.dofusdb.fr/img/items/180004.png" alt="item"><span>Sachet de Citrons</span></span>)</p></div></li></ul><p>Ensuite <span style="color: rgb(255, 255, 0);">fabriquez </span>des <span data-type="custom-tag" data-id="17173" class="tag-item" id="10009" type="item" name="Papillote au Citron" imageurl="https://api.dofusdb.fr/img/items/69744.png" dofusdbid="17173"><img src="https://api.dofusdb.fr/img/items/69744.png" alt="item"><span>Papillote au Citron</span></span><span style="color: rgb(255, 255, 255);">.</span></p><p><span style="color: rgb(5, 160, 69);">Astuces :</span></p><p>1️⃣ Dans l''<span style="color: rgb(255, 255, 0);">encyclopédie</span> (touche "<span style="color: rgb(255, 255, 0);">b</span>"), <span style="color: rgb(255, 255, 0);">recherchez </span>dans les <span style="color: rgb(255, 255, 0);">ressources </span>la <span data-type="custom-tag" data-id="17128" class="tag-item" id="9964" type="item" name="Viande Minérale" imageurl="https://api.dofusdb.fr/img/items/63411.png" dofusdbid="17128"><img src="https://api.dofusdb.fr/img/items/63411.png" alt="item"><span>Viande Minérale</span></span>.</p><p>Ensuite faites <span style="color: rgb(255, 255, 255);">un</span> <span style="color: rgb(255, 255, 0);">clic droit </span><span style="color: rgb(255, 255, 255);">sur celle-ci</span><span style="color: rgb(255, 255, 0);"> </span>puis <span style="color: rgb(255, 255, 0);">Bestiaire </span>pour voir sur<span style="color: rgb(255, 255, 0);"> quels monstres l''obtenir</span> ainsi que le <span style="color: rgb(255, 255, 0);">taux de drop</span>.</p>', 0, 'Introduction', NULL, '#a855f7', 0, 640, true, '{}', 20, '2026-05-02 12:06:57.959', '2026-05-02 12:06:57.959');
INSERT INTO public."GuideMilestone" VALUES ('cmooaqqi6001oygogqjlbi6oc', 'cmolc84qt0000noogp0gr4sjj', 'DONJON', 'Sufokia, Tour du Monde et Alignement.', NULL, '<p><span style="color: rgb(250, 0, 0);">Objectifs :</span> Sufokia, Tour du Monde et Alignement.</p><p>Pour cette étape, si vous êtes <span style="color: rgb(66, 165, 246);">bontarien </span><span style="color: rgb(255, 255, 0);">avancez </span>les <span style="color: rgb(255, 255, 0);">2 guides </span>jusqu''à atteindre le <span data-type="custom-tag" data-id="21" class="tag-dungeon" id="16" type="dungeon" name="Donjon des Forgerons" imageurl="https://ganymede-app.com/images/icon_dungeon.png" dofusdbid="21"><img src="https://ganymede-app.com/images/icon_dungeon.png" alt="dungeon"><span>Donjon des Forgerons</span></span>.</p><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p>(<span style="color: rgb(170, 71, 188);">Optionnel</span>) <span style="color: rgb(255, 255, 0);">Reprenez </span>le guide <span data-type="guide-step" class="guide-step" guideid="310" stepid="0" stepnumber="1" guidename="[GP5] Sufokia" label="[GP5] Sufokia" baseurl="https://ganymede-dofus.com"><img src="https://ganymede-dofus.com/images/texteditor/guides.png" alt="GuideStep">[GP5] Sufokia</span> de l''<span style="color: rgb(255, 255, 0);">étape 23&nbsp;</span>jusqu''à l''<span style="color: rgb(255, 255, 0);">étape 29</span> incluse.</p></div></li></ul><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p>Si vous êtes <span style="color: rgb(98, 172, 255);">Bontarien</span>, <span style="color: rgb(255, 255, 0);">continuez </span>le guide <span data-type="guide-step" class="guide-step" guideid="516" stepid="0" stepnumber="1" guidename="[GP9] ALIGNEMENT BONTARIEN" label="[GP9] Alignement Bontarien" baseurl="https://ganymede-dofus.com"><img src="https://ganymede-dofus.com/images/texteditor/guides.png" alt="GuideStep">[GP9] Alignement Bontarien</span> de l''<span style="color: rgb(255, 255, 0);">étape 6</span> jusqu''à l''<span style="color: rgb(255, 255, 0);">étape 37</span> incluse.</p></div></li></ul><div data-type="quest-block" class="quest-block" title="Les sbires du maître" questid="83" questname="Les sbires du maître" status="in_progress"><p><span style="color: rgb(255, 255, 0);">Réalisez </span>le <span data-type="custom-tag" data-id="21" class="tag-dungeon" id="16" type="dungeon" name="Donjon des Forgerons" imageurl="https://ganymede-dofus.com/images/icon_dungeon.png" dofusdbid="21"><img src="https://ganymede-dofus.com/images/icon_dungeon.png" alt="dungeon"><span>Donjon des Forgerons</span></span> et</p></div><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p><span style="color: rgb(255, 255, 255);">Si vous êtes</span><span style="color: rgb(250, 0, 0);"> </span><span style="color: rgb(98, 172, 255);">Bontarien</span><span style="color: rgb(255, 255, 255);">,&nbsp;</span><span style="color: rgb(255, 255, 0);">cliquez </span>sur la <span style="color: rgb(255, 255, 0);">marmite </span>à la <span style="color: rgb(98, 172, 255);">fin du donjon</span>.</p></div></li></ul><div data-type="quest-block" class="quest-block" title="Les sbires du maître" questid="83" questname="Les sbires du maître" status="in_progress"><p><span style="color: rgb(98, 172, 255);">Allez en</span> [5,0] et parlez à <span style="color: rgb(255, 255, 0);">Pat Akess.</span></p></div>', 5, '[GP5] Sufokia', NULL, '#8b5cf6', 220, 800, false, '{}', 21, '2026-05-02 12:06:57.966', '2026-05-02 12:06:57.966');
INSERT INTO public."GuideMilestone" VALUES ('cmooaqqin001rygogiixtpwng', 'cmolc84qt0000noogp0gr4sjj', 'DONJON', 'Tour du Monde et Alignement.', NULL, '<p><span style="color: rgb(250, 0, 0);">Objectif : </span>Tour du Monde et Alignement.</p><p><span style="color: rgb(250, 0, 0);">Lisez bien toute l''étape avant de la faire !</span></p><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p><span style="color: rgb(255, 255, 255);">Si vous êtes</span><span style="color: rgb(100, 181, 246);"> </span><span style="color: rgb(235, 65, 101);">Brâkmarien</span>, <span style="color: rgb(255, 255, 0);">reprenez </span>le guide <span data-type="guide-step" class="guide-step" guideid="773" stepid="0" stepnumber="1" guidename="[GP9] ALIGNEMENT BRÂKMARIEN" label="[GP9] Alignement Brâkmarien" baseurl="https://ganymede-dofus.com"><img src="https://ganymede-dofus.com/images/texteditor/guides.png" alt="GuideStep">[GP9] Alignement Brâkmarien</span> de l''<span style="color: rgb(255, 255, 0);">étape 5</span> jusqu''à l''<span style="color: rgb(255, 255, 0);">étape 21</span> incluse.</p></div></li></ul><div data-type="quest-block" class="quest-block" title="Donjon douillet" questid="624" questname="Donjon douillet" status="in_progress"><p><span style="color: rgb(255, 255, 0);">Réalisez </span>le <span data-type="custom-tag" data-id="32" class="tag-dungeon" id="24" type="dungeon" name="Nid du Kwakwa" imageurl="https://ganymede-dofus.com/images/icon_dungeon.png" dofusdbid="32"><img src="https://ganymede-dofus.com/images/icon_dungeon.png" alt="dungeon"><span>Nid du Kwakwa</span></span>1️⃣ et</p></div><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p>Parlez à l''<span style="color: rgb(255, 255, 0);">Esprit volatile </span>à la <span style="color: rgb(98, 172, 255);">fin du donjon</span> pour <span style="color: rgb(255, 255, 0);">obtenir </span>le sort <span style="color: rgb(255, 255, 0);">Capture d''Âme2️⃣</span>.</p></div></li><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p><span style="color: rgb(255, 255, 255);">Si vous êtes</span><span style="color: rgb(100, 181, 246);"> </span><span style="color: rgb(235, 65, 101);">Brâkmarien</span>, <span style="color: rgb(255, 255, 0);">cliquez </span>sur l''<span style="color: rgb(255, 255, 0);">œuf</span> à la <span style="color: rgb(98, 172, 255);">fin du donjon</span>.</p></div></li></ul><div data-type="quest-block" class="quest-block" title="Donjon douillet" questid="624" questname="Donjon douillet" status="end"><p><span style="color: rgb(98, 172, 255);">Allez en</span> [1,-15] et parlez à <span style="color: rgb(255, 255, 0);">Emma Tompouce</span> pour finir <span data-type="custom-tag" data-id="898" class="tag-quest" id="624" type="quest" name="Donjon douillet" imageurl="https://ganymede-dofus.com/images/icon_quest.png" dofusdbid="898"><img src="https://ganymede-dofus.com/images/icon_quest.png" alt="quest"><span>Donjon douillet</span></span>.</p></div><div data-type="quest-block" class="quest-block" title="Donjon magistral" questid="625" questname="Donjon magistral" status="start"><p><span style="color: rgb(255, 255, 0);">Continuez </span>de lui <span style="color: rgb(255, 255, 0);">parler </span>pour lancer <span data-type="custom-tag" data-id="899" class="tag-quest" id="625" type="quest" name="Donjon magistral" imageurl="https://ganymede-dofus.com/images/icon_quest.png" dofusdbid="899"><img src="https://ganymede-dofus.com/images/icon_quest.png" alt="quest"><span>Donjon magistral</span></span>.</p></div><p><span style="color: rgb(5, 160, 69);">Astuces :</span></p><p>1️⃣ Faites un <span style="color: rgb(255, 255, 0);">challenge </span>sur les<span style="color: rgb(255, 255, 0);"> </span><span style="color: rgb(98, 172, 255);">salles 1 à 4 </span>du donjon<span style="color: rgb(255, 255, 0);"> </span>pour <span style="color: rgb(255, 255, 0);">obtenir </span>le <span style="color: rgb(255, 255, 0);">succès monstre</span>.</p><p>2️⃣ Le sort <span style="color: rgb(255, 255, 0);">Capture d''Âme</span><span style="color: rgb(255, 255, 255);"> permet de </span><span style="color: rgb(255, 255, 0);">capturer </span><span style="color: rgb(255, 255, 255);">un </span><span style="color: rgb(255, 255, 0);">groupe de monstre </span><span style="color: rgb(255, 255, 255);">pour le </span><span data-type="custom-tag" data-id="7754" class="tag-item" id="2502" type="item" name="Dofus Ocre" imageurl="https://api.dofusdb.fr/img/items/23012.png" dofusdbid="7754"><img src="https://api.dofusdb.fr/img/items/23012.png" alt="item"><span>Dofus Ocre</span></span> <span style="color: rgb(255, 255, 255);">ou pour le </span><span style="color: rgb(255, 255, 0);">recombattre </span><span style="color: rgb(255, 255, 255);">en </span><span style="color: rgb(255, 255, 0);">arène</span><span style="color: rgb(255, 255, 255);">.</span></p>', 9, '[GP9] ALIGNEMENT BRÂKMARIEN', NULL, '#8b5cf6', 440, 800, false, '{}', 22, '2026-05-02 12:06:57.983', '2026-05-02 12:06:57.983');
INSERT INTO public."GuideMilestone" VALUES ('cmooaqqiw001tygogh71a099j', 'cmolc84qt0000noogp0gr4sjj', 'PREREQUIS', '👉 Étape bonus 👈', NULL, '<p style="text-align: center;"><span style="color: rgb(5, 160, 69);"><strong>👉 Étape bonus 👈</strong></span></p><p style="text-align: center;">🗡️ Mise à jour de l''équipement 🗡️</p><p>Pour la tranche de <span style="color: rgb(255, 255, 0);">niveau 40-60</span>, le combo <span style="color: rgb(255, 255, 0);">Panoplie Kwak</span> et<span style="color: rgb(255, 255, 0);"> Panoplie Blop</span> est très facile à obtenir.</p><p>La <span style="color: rgb(255, 255, 0);">panoplie Kwak</span> se <span style="color: rgb(255, 255, 0);">drop </span>sur les <span style="color: rgb(255, 255, 0);">Kwaks </span>et la <span style="color: rgb(255, 255, 0);">Panoplie Blop</span> se fabrique <span style="color: rgb(255, 255, 0);">sans </span>les <span style="color: rgb(255, 255, 0);">ressources des métiers</span> de <span style="color: rgb(255, 255, 0);">récolte</span>.</p><p><span style="color: rgb(255, 255, 255);">Voici un </span><span style="color: rgb(255, 255, 0);">exemple </span><span style="color: rgb(255, 255, 255);">d''</span><span style="color: rgb(255, 255, 0);">équipement1️⃣2️⃣3️⃣</span><span style="color: rgb(255, 255, 255);"> selon l''élément :</span></p><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p><a target="_blank" rel="noopener noreferrer nofollow" href="https://www.dofusbook.net/fr/equipement/17727986-db/objets"><span style="color: rgb(115, 67, 9);">Terre</span></a></p></div></li><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p><a target="_blank" rel="noopener noreferrer nofollow" href="https://www.dofusbook.net/fr/equipement/17778793-db/objets"><span style="color: rgb(66, 165, 246);">Eau</span></a></p></div></li><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p><a target="_blank" rel="noopener noreferrer nofollow" href="https://www.dofusbook.net/fr/equipement/17727958-db/objets"><span style="color: rgb(235, 65, 101);">Feu</span></a></p></div></li><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p><a target="_blank" rel="noopener noreferrer nofollow" href="https://www.dofusbook.net/fr/equipement/17727921-db/objets"><span style="color: rgb(131, 198, 131);">Air</span></a></p></div></li></ul><p><span style="color: rgb(5, 160, 69);">Astuces :</span></p><p>1️⃣ Il n''y a volontairement ni les <span style="color: rgb(255, 255, 0);">trophées </span>ni de <span style="color: rgb(255, 255, 0);">compagnon</span> dans les <span style="color: rgb(255, 255, 0);">équipements</span>, vous êtes libre.</p><p>2️⃣ <span style="color: rgb(255, 255, 255);">Pensez à </span><span style="color: rgb(255, 255, 0);">FM </span><span style="color: rgb(255, 255, 255);">votre </span><span style="color: rgb(255, 255, 0);">arme </span><span style="color: rgb(255, 255, 255);">avec </span>une <span data-type="custom-tag" data-id="10057" class="tag-item" id="4249" type="item" name="Rune de chasse" imageurl="https://api.dofusdb.fr/img/items/78059.png" dofusdbid="10057"><img src="https://api.dofusdb.fr/img/items/78059.png" alt="item"><span>Rune de chasse</span></span> si vous êtes <span style="color: rgb(255, 255, 0);">chasseur</span>.</p><p>3️⃣ Pour voir la liste des <span style="color: rgb(255, 255, 0);">ingrédients nécessaires </span><span style="color: rgb(255, 255, 255);">à la fabrication complète de l''équipement</span>, utilisez les <span style="color: rgb(255, 255, 0);">liens DofusBook </span>ci-dessus puis :</p><p><span style="color: rgb(255, 255, 0);">Cliquez </span>sur <span style="color: rgb(255, 255, 0);">Détails du craft de ce stuff </span>(logo d''un marteau)<span style="color: rgb(255, 255, 0);"> </span>et <span style="color: rgb(255, 255, 0);">sélectionnez </span>les <span style="color: rgb(255, 255, 0);">items </span>à <span style="color: rgb(255, 255, 0);">fabriquer</span>.</p>', 0, 'Introduction', NULL, '#a855f7', 660, 800, true, '{}', 23, '2026-05-02 12:06:57.992', '2026-05-02 12:06:57.992');
INSERT INTO public."GuideMilestone" VALUES ('cmooaqqj1001uygog0pusnkem', 'cmolc84qt0000noogp0gr4sjj', 'DOFUS', 'Île d''Otomaï.', NULL, '<p><span style="color: rgb(250, 0, 0);">Objectif :</span> Île d''Otomaï.</p><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p><span style="color: rgb(255, 255, 0);">Commencez </span>le guide <span data-type="guide-step" class="guide-step" guideid="183" stepid="0" stepnumber="1" guidename="[GP6] OTOMAÏ 1" label="[GP6] Otomaï 1" baseurl="https://ganymede-dofus.com"><img src="https://ganymede-dofus.com/images/texteditor/guides.png" alt="GuideStep">[GP6] Otomaï 1</span>1️⃣ jusqu''à l''<span style="color: rgb(255, 255, 0);">étape 4</span> incluse.</p></div></li></ul><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p>Si vous ne l''avez <span style="color: rgb(255, 255, 0);">pas fini</span>, <span style="color: rgb(255, 255, 0);">terminez </span><span style="color: rgb(255, 255, 255);">le guide </span><span data-type="guide-step" class="guide-step" guideid="3" stepid="0" stepnumber="1" guidename="[GP4] Mais où sont les dofus ?" label="[GP4] Mais où sont les dofus ?" baseurl="https://ganymede-dofus.com"><img src="https://ganymede-dofus.com/images/texteditor/guides.png" alt="GuideStep">[GP4] Mais où sont les dofus ?</span>.</p></div></li></ul><p><span style="color: rgb(5, 160, 69);">Astuce :</span></p><p>1️⃣ Vous accédez à l''<span style="color: rgb(98, 172, 255);">Île d''Otomaï</span> pour <span style="color: rgb(255, 255, 0);">débloquer </span>le <span style="color: rgb(98, 172, 255);">Zaap </span>du <span style="color: rgb(98, 172, 255);">Village Côtier</span>.</p>', 6, '[GP6] OTOMAÏ 1', NULL, '#f59e0b', 0, 800, false, '{}', 24, '2026-05-02 12:06:57.997', '2026-05-02 12:06:57.997');
INSERT INTO public."GuideMilestone" VALUES ('cmooaqqjh001xygogqp7uh4z6', 'cmolc84qt0000noogp0gr4sjj', 'DONJON', 'Ocre d''Ambre et Gobelins et Bworks.', NULL, '<p><span style="color: rgb(250, 0, 0);">Objectifs :</span> Ocre d''Ambre et Gobelins et Bworks.</p><p><span style="color: rgb(250, 0, 0);">Lisez bien toute l''étape avant de la faire !</span></p><p>Pour cette étape, <span style="color: rgb(255, 255, 0);">avancez </span>les <span style="color: rgb(255, 255, 0);">2 guides </span>jusqu''à atteindre l''<span data-type="custom-tag" data-id="138" class="tag-dungeon" id="120" type="dungeon" name="Akadémie des Gobs" imageurl="https://ganymede-dofus.com/images/icon_dungeon.png" dofusdbid="138"><img src="https://ganymede-dofus.com/images/icon_dungeon.png" alt="dungeon"><span>Akadémie des Gobs</span></span>.</p><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p>(<span style="color: rgb(170, 71, 188);">Optionnel</span>) <span style="color: rgb(255, 255, 0);">Commencez </span>le<span style="color: rgb(255, 255, 0);"> </span><span style="color: rgb(255, 255, 255);">guide </span><span data-type="guide-step" class="guide-step" guideid="28" stepid="0" stepnumber="1" guidename="[GP10] Gobelins et Bworks" label="[GP10] Gobelins et Bworks" baseurl="https://ganymede-dofus.com"><img src="https://ganymede-dofus.com/images/texteditor/guides.png" alt="GuideStep">[GP10] Gobelins et Bworks</span>1️⃣ jusqu''à l''<span style="color: rgb(255, 255, 0);">étape 11</span> incluse.</p></div></li></ul><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p><span style="color: rgb(255, 255, 0);">Commencez </span>le guide <span data-type="guide-step" class="guide-step" guideid="104" stepid="0" stepnumber="1" guidename="[GP7] Ocre d''Ambre" label="[GP7] Ocre d''Ambre" baseurl="https://ganymede-dofus.com"><img src="https://ganymede-dofus.com/images/texteditor/guides.png" alt="GuideStep">[GP7] Ocre d''Ambre</span>1️⃣ jusqu''à l''<span style="color: rgb(255, 255, 0);">étape 6</span> incluse.</p></div></li></ul><p><span style="color: rgb(255, 255, 0);">Réalisez </span>l''<span data-type="custom-tag" data-id="138" class="tag-dungeon" id="120" type="dungeon" name="Akadémie des Gobs" imageurl="https://ganymede-app.com/images/icon_dungeon.png" dofusdbid="138"><img src="https://ganymede-app.com/images/icon_dungeon.png" alt="dungeon"><span>Akadémie des Gobs</span></span>2️⃣.</p><p><span style="color: rgb(5, 160, 69);">Astuces :</span></p><p>1️⃣ <span style="color: rgb(250, 0, 0);">Attention !</span> Lisez l''<span style="color: rgb(5, 160, 69);">astuce</span>&nbsp;à l''<span style="color: rgb(255, 255, 0);">étape 6</span> du guide <span data-type="guide-step" class="guide-step" guideid="104" stepid="0" stepnumber="1" guidename="[GP7] Ocre d''Ambre" label="[GP7] Ocre d''Ambre" baseurl="https://ganymede-dofus.com"><img src="https://ganymede-dofus.com/images/texteditor/guides.png" alt="GuideStep">[GP7] Ocre d''Ambre</span>&nbsp;pour l''<span style="color: rgb(255, 255, 0);">ordre </span>des <span style="color: rgb(255, 255, 0);">dialogues</span>.</p><p>La série de quête <span style="color: rgb(255, 255, 0);">Ocre d''Ambre</span> va vous <span style="color: rgb(255, 255, 0);">initier </span>aux <span data-type="custom-tag" data-id="26280" class="tag-item" id="16473" type="item" name="Boîte de Bouataklône" imageurl="https://api.dofusdb.fr/img/items/15192.png" dofusdbid="26280"><img src="https://api.dofusdb.fr/img/items/15192.png" alt="item"><span>Boîte de Bouataklône</span></span> et aux <span data-type="custom-tag" data-id="26264" class="tag-item" id="16457" type="item" name="Truk divin" imageurl="https://api.dofusdb.fr/img/items/15266.png" dofusdbid="26264"><img src="https://api.dofusdb.fr/img/items/15266.png" alt="item"><span>Truk divin</span></span>.</p><p>A l''<span style="color: rgb(255, 255, 0);">étape 6</span> du guide, vous lancez aussi l''<span data-type="custom-tag" data-id="439" class="tag-quest" id="263" type="quest" name="L''éternelle moisson" imageurl="https://ganymede-dofus.com/images/icon_quest.png" dofusdbid="439"><img src="https://ganymede-dofus.com/images/icon_quest.png" alt="quest"><span>L''éternelle moisson</span></span>&nbsp;pour le <span data-type="custom-tag" data-id="7754" class="tag-item" id="2502" type="item" name="Dofus Ocre" imageurl="https://api.dofusdb.fr/img/items/23012.png" dofusdbid="7754"><img src="https://api.dofusdb.fr/img/items/23012.png" alt="item"><span>Dofus Ocre</span></span>.</p><p>Vous <span style="color: rgb(255, 255, 0);">trouverez </span>toutes les <span style="color: rgb(255, 255, 0);">explications </span>dans le guide <span data-type="guide-step" class="guide-step" guideid="182" stepid="0" stepnumber="1" guidename="[GP8] DOFUS OCRE" label="[GP8] Dofus Ocre" baseurl="https://ganymede-dofus.com"><img src="https://ganymede-dofus.com/images/texteditor/guides.png" alt="GuideStep">[GP8] Dofus Ocre</span>.</p><p>Vous serez initié au sort <span style="color: rgb(255, 255, 0);">Capture d''âme</span><span style="color: rgb(255, 255, 255);">, où vous devez capturer des monstres et boss pour obtenir le </span><span data-type="custom-tag" data-id="7754" class="tag-item" id="2502" type="item" name="Dofus Ocre" imageurl="https://api.dofusdb.fr/img/items/23012.png" dofusdbid="7754"><img src="https://api.dofusdb.fr/img/items/23012.png" alt="item"><span>Dofus Ocre</span></span>.</p><p>L''<span style="color: rgb(255, 255, 0);">indication </span>"(<span data-type="custom-tag" data-id="7754" class="tag-item" id="2502" type="item" name="Dofus Ocre" imageurl="https://api.dofusdb.fr/img/items/23012.png" dofusdbid="7754"><img src="https://api.dofusdb.fr/img/items/23012.png" alt="item"><span>Dofus Ocre</span></span>)" vous <span style="color: rgb(255, 255, 0);">informera </span>des <span style="color: rgb(255, 255, 0);">boss </span>nécessaires <span style="color: rgb(255, 255, 0);">à capturer</span> pour celui-ci.</p><p>2️⃣ Faites un <span style="color: rgb(255, 255, 0);">challenge </span>sur un <span data-type="custom-tag" data-id="6900" class="tag-monster" id="4469" type="monster" name="Gobichon" imageurl="https://api.dofusdb.fr/img/monsters/1180.png" dofusdbid="6900"><img src="https://api.dofusdb.fr/img/monsters/1180.png" alt="monster"><span>Gobichon</span></span> pour le succès monstre.</p>', 10, '[GP10] Gobelins et Bworks', NULL, '#8b5cf6', 220, 960, false, '{}', 25, '2026-05-02 12:06:58.013', '2026-05-02 12:06:58.013');
INSERT INTO public."GuideMilestone" VALUES ('cmooaqqk40021ygogrwrp8uw3', 'cmolc84qt0000noogp0gr4sjj', 'DOFUS', 'Tour du Monde et Gobelins et Bworks.', NULL, '<p><span style="color: rgb(250, 0, 0);">Objectifs :</span> Tour du Monde et Gobelins et Bworks.</p><div data-type="quest-block" class="quest-block" title="Les sbires du maître" questid="83" questname="Les sbires du maître" status="in_progress"><p><span style="color: rgb(255, 255, 0);">Réalisez </span>le <span data-type="custom-tag" data-id="13" class="tag-dungeon" id="10" type="dungeon" name="Donjon des Bworks" imageurl="https://ganymede-dofus.com/images/icon_dungeon.png" dofusdbid="13"><img src="https://ganymede-dofus.com/images/icon_dungeon.png" alt="dungeon"><span>Donjon des Bworks</span></span> (<span data-type="custom-tag" data-id="7754" class="tag-item" id="2502" type="item" name="Dofus Ocre" imageurl="https://api.dofusdb.fr/img/items/23012.png" dofusdbid="7754"><img src="https://api.dofusdb.fr/img/items/23012.png" alt="item"><span>Dofus Ocre</span></span>).</p></div><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p>(<span style="color: rgb(170, 71, 188);">Optionnel</span>) <span style="color: rgb(255, 255, 0);">Terminez </span><span style="color: rgb(255, 255, 255);">le guide </span><span data-type="guide-step" class="guide-step" guideid="28" stepid="0" stepnumber="1" guidename="[GP10] Gobelins et Bworks" label="[GP10] Gobelins et Bworks" baseurl="https://ganymede-dofus.com"><img src="https://ganymede-dofus.com/images/texteditor/guides.png" alt="GuideStep">[GP10] Gobelins et Bworks</span> depuis l''<span style="color: rgb(255, 255, 0);">étape 12</span>.</p></div></li></ul><div data-type="quest-block" class="quest-block" title="Les sbires du maître" questid="83" questname="Les sbires du maître" status="in_progress"><p><span style="color: rgb(98, 172, 255);">Allez en</span> [5,0] et parlez à <span style="color: rgb(255, 255, 0);">Pat Akess</span>.</p></div>', 10, '[GP10] Gobelins et Bworks', NULL, '#f59e0b', 440, 960, false, '{}', 26, '2026-05-02 12:06:58.036', '2026-05-02 12:06:58.036');
INSERT INTO public."GuideMilestone" VALUES ('cmooaqqkf0023ygogepnkxt7b', 'cmolc84qt0000noogp0gr4sjj', 'DONJON', 'Tour du Monde et Alignement.', NULL, '<p><span style="color: rgb(250, 0, 0);">Objectifs :</span> Tour du Monde et Alignement.</p><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p><span style="color: rgb(255, 255, 255);">Si vous êtes</span><span style="color: rgb(100, 181, 246);"> </span><span style="color: rgb(235, 65, 101);">Brâkmarien</span>,<span style="color: rgb(100, 181, 246);"> </span><span style="color: rgb(255, 255, 0);">reprenez </span><span style="color: rgb(255, 255, 255);">le guide </span><span data-type="guide-step" class="guide-step" guideid="773" stepid="0" stepnumber="1" guidename="[GP9] ALIGNEMENT BRÂKMARIEN" label="[GP9] Alignement Brâkmarien" baseurl="https://ganymede-dofus.com"><img src="https://ganymede-dofus.com/images/texteditor/guides.png" alt="GuideStep">[GP9] Alignement Brâkmarien</span> de l''<span style="color: rgb(255, 255, 0);">étape 21&nbsp;</span>jusqu''à l''<span style="color: rgb(255, 255, 0);">étape 261️⃣</span> incluse.</p></div></li></ul><div data-type="quest-block" class="quest-block" title="Les sbires du maître" questid="83" questname="Les sbires du maître" status="in_progress"><p><span style="color: rgb(255, 255, 0);">Réalisez </span>le <span data-type="custom-tag" data-id="33" class="tag-dungeon" id="25" type="dungeon" name="Donjon des Larves" imageurl="https://ganymede-dofus.com/images/icon_dungeon.png" dofusdbid="33"><img src="https://ganymede-dofus.com/images/icon_dungeon.png" alt="dungeon"><span>Donjon des Larves</span></span>2️⃣3️⃣ (<span data-type="custom-tag" data-id="7754" class="tag-item" id="2502" type="item" name="Dofus Ocre" imageurl="https://api.dofusdb.fr/img/items/23012.png" dofusdbid="7754"><img src="https://api.dofusdb.fr/img/items/23012.png" alt="item"><span>Dofus Ocre</span></span>) et</p></div><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p><span style="color: rgb(255, 255, 255);">Si vous êtes</span><span style="color: rgb(100, 181, 246);"> </span><span style="color: rgb(235, 65, 101);">Brâkmarien</span>,<span style="color: rgb(250, 0, 0);"> </span>parlez&nbsp;à la <span style="color: rgb(255, 255, 0);">Larve Dorée</span> à la <span style="color: rgb(98, 172, 255);">fin du donjon</span>.</p></div></li></ul><div data-type="quest-block" class="quest-block" title="Les sbires du maître" questid="83" questname="Les sbires du maître" status="in_progress"><p><span style="color: rgb(98, 172, 255);">Allez en</span> [5,0] et parlez à <span style="color: rgb(255, 255, 0);">Pat Akess</span>.</p></div><p><span style="color: rgb(5, 160, 69);">Astuces :</span></p><p>1️⃣ Si vous êtes <span style="color: rgb(235, 29, 78);">brâkmarien</span>, n''utilisez pas l''<span data-type="custom-tag" data-id="7423" class="tag-item" id="2344" type="item" name="Œuf de Larve Dorée" imageurl="https://api.dofusdb.fr/img/items/12715.png" dofusdbid="7423"><img src="https://api.dofusdb.fr/img/items/12715.png" alt="item"><span>Œuf de Larve Dorée</span></span> pour entrer, mais bien la<span style="color: rgb(255, 255, 0);"> larve donnée par Oto Mustam</span>.</p><p>2️⃣ Ce donjon <span style="color: rgb(255, 255, 0);">nécessite </span>l''<span style="color: rgb(255, 255, 0);">aide</span> d''un <span style="color: rgb(255, 255, 0);">autre joueur</span> à l''intérieur pour <span style="color: rgb(255, 255, 0);">ouvrir 2 passages</span>.</p><p>Ce donjon n''a <span style="color: rgb(255, 255, 0);">pas de gardien</span> et donc vous ne pouvez<span style="color: rgb(255, 255, 0);"> pas téléporter</span> d''<span style="color: rgb(255, 255, 0);">autres joueurs</span>.</p><p>Pour <span style="color: rgb(98, 172, 255);">entrer</span>,<span style="color: rgb(255, 255, 0);"> double cliquez</span> sur l''<span data-type="custom-tag" data-id="7423" class="tag-item" id="2344" type="item" name="Œuf de Larve Dorée" imageurl="https://api.dofusdb.fr/img/items/12715.png" dofusdbid="7423"><img src="https://api.dofusdb.fr/img/items/12715.png" alt="item"><span>Œuf de Larve Dorée</span></span> dans vos consommables.</p><p><br>3️⃣ Pensez à réaliser un <span style="color: rgb(255, 255, 0);">challenge </span>sur les <span style="color: rgb(255, 255, 0);">larves </span>suivantes :</p><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p><span data-type="custom-tag" data-id="412" class="tag-monster" id="230" type="monster" name="Larve Saphir" imageurl="https://api.dofusdb.fr/img/monsters/217.png" dofusdbid="412"><img src="https://api.dofusdb.fr/img/monsters/217.png" alt="monster"><span>Larve Saphir</span></span></p></div></li><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p><span data-type="custom-tag" data-id="413" class="tag-monster" id="231" type="monster" name="Larve Rubis" imageurl="https://api.dofusdb.fr/img/monsters/218.png" dofusdbid="413"><img src="https://api.dofusdb.fr/img/monsters/218.png" alt="monster"><span>Larve Rubis</span></span></p></div></li><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p><span data-type="custom-tag" data-id="414" class="tag-monster" id="232" type="monster" name="Larve Émeraude" imageurl="https://api.dofusdb.fr/img/monsters/219.png" dofusdbid="414"><img src="https://api.dofusdb.fr/img/monsters/219.png" alt="monster"><span>Larve Émeraude</span></span></p></div></li><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p><span data-type="custom-tag" data-id="456" class="tag-monster" id="260" type="monster" name="Larve Dorée" imageurl="https://api.dofusdb.fr/img/monsters/216.png" dofusdbid="456"><img src="https://api.dofusdb.fr/img/monsters/216.png" alt="monster"><span>Larve Dorée</span></span></p></div></li></ul>', 9, '[GP9] ALIGNEMENT BRÂKMARIEN', NULL, '#8b5cf6', 660, 960, false, '{}', 27, '2026-05-02 12:06:58.047', '2026-05-02 12:06:58.047');
INSERT INTO public."GuideMilestone" VALUES ('cmooaqqkq0025ygogtwvmn3vu', 'cmolc84qt0000noogp0gr4sjj', 'DONJON', 'Tour du Monde et Valonia 1.', NULL, '<p><span style="color: rgb(250, 0, 0);">Objectifs :</span> Tour du Monde et Valonia 1.</p><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p><span style="color: rgb(255, 255, 0);">Commencez </span>et <span style="color: rgb(255, 255, 0);">terminez </span>le guide <span data-type="guide-step" class="guide-step" guideid="25" stepid="0" stepnumber="1" guidename="[GP11] Valonia 1 : Albuera" label="[GP11] Valonia 1 : Albuera" baseurl="https://ganymede-dofus.com"><img src="https://ganymede-dofus.com/images/texteditor/guides.png" alt="GuideStep">[GP11] Valonia 1 : Albuera</span>.</p></div></li></ul><div data-type="quest-block" class="quest-block" title="Les sbires du maître" questid="83" questname="Les sbires du maître" status="in_progress"><p><span style="color: rgb(255, 255, 0);">Réalisez </span>le <span data-type="custom-tag" data-id="142" class="tag-dungeon" id="124" type="dungeon" name="Refuge sylvestre" imageurl="https://ganymede-dofus.com/images/icon_dungeon.png" dofusdbid="142"><img src="https://ganymede-dofus.com/images/icon_dungeon.png" alt="dungeon"><span>Refuge sylvestre</span></span>1️⃣(<span data-type="custom-tag" data-id="7754" class="tag-item" id="2502" type="item" name="Dofus Ocre" imageurl="https://api.dofusdb.fr/img/items/23012.png" dofusdbid="7754"><img src="https://api.dofusdb.fr/img/items/23012.png" alt="item"><span>Dofus Ocre</span></span>).</p></div><div data-type="quest-block" class="quest-block" title="Les sbires du maître" questid="83" questname="Les sbires du maître" status="in_progress"><p><span style="color: rgb(98, 172, 255);">Allez en</span> [5,0] et parlez à <span style="color: rgb(255, 255, 0);">Pat Akess</span>.</p></div><p><span style="color: rgb(5, 160, 69);">Astuce :</span></p><p>1️⃣ Faites un <span style="color: rgb(255, 255, 0);">challenge</span> sur un <span data-type="custom-tag" data-id="7196" class="tag-monster" id="4545" type="monster" name="Trankilou" imageurl="https://api.dofusdb.fr/img/monsters/2318.png" dofusdbid="7196"><img src="https://api.dofusdb.fr/img/monsters/2318.png" alt="monster"><span>Trankilou</span></span>.</p>', 11, '[GP11] Valonia 1 : Albuera', NULL, '#8b5cf6', 0, 960, false, '{}', 28, '2026-05-02 12:06:58.058', '2026-05-02 12:06:58.058');
INSERT INTO public."GuideMilestone" VALUES ('cmooaqql00027ygogmetzo2u7', 'cmolc84qt0000noogp0gr4sjj', 'DONJON', 'Ocre d''ambre, Justiciers et Tour du Monde.', NULL, '<p><span style="color: rgb(250, 0, 0);">Objectifs : </span>Ocre d''ambre, Justiciers et Tour du Monde.</p><p><span style="color: rgb(250, 0, 0);">Lisez bien toute l''étape avant de la faire !</span></p><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p><span style="color: rgb(255, 255, 0);">Commencez </span>le guide&nbsp;<span data-type="guide-step" class="guide-step" guideid="430" stepid="0" stepnumber="1" guidename="[GP23] Justiciers et plus" label="[GP23] Justiciers et plus" baseurl="https://ganymede-app.com"><img src="https://ganymede-app.com/images/texteditor/guides.png" alt="GuideStep">[GP23] Justiciers et plus</span>&nbsp;jusqu''à l''<span style="color: rgb(255, 255, 0);">étape 6</span> incluse pour finir&nbsp;<span data-type="custom-tag" data-id="1423" class="tag-quest" id="1137" type="quest" name="Protéger et sévir" imageurl="https://ganymede-app.com/images/icon_quest.png" dofusdbid="1423"><img src="https://ganymede-app.com/images/icon_quest.png" alt="quest"><span>Protéger et sévir</span></span>.</p></div></li></ul><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p><span style="color: rgb(255, 255, 0);">Continuez </span>le guide <span data-type="guide-step" class="guide-step" guideid="104" stepid="0" stepnumber="1" guidename="[GP7] Ocre d''Ambre" label="[GP7] Ocre d''Ambre" baseurl="https://ganymede-dofus.com"><img src="https://ganymede-dofus.com/images/texteditor/guides.png" alt="GuideStep">[GP7] Ocre d''Ambre</span> de l''<span style="color: rgb(255, 255, 0);">étape 6&nbsp;</span>jusqu''à l''<span style="color: rgb(255, 255, 0);">étape 11</span> incluse.</p></div></li></ul><div data-type="quest-block" class="quest-block" title="Donjon magistral" questid="625" questname="Donjon magistral" status="in_progress"><p><span style="color: rgb(255, 255, 0);">Réalisez </span>la <span data-type="custom-tag" data-id="25" class="tag-dungeon" id="19" type="dungeon" name="Grotte Hesque" imageurl="https://ganymede-dofus.com/images/icon_dungeon.png" dofusdbid="25"><img src="https://ganymede-dofus.com/images/icon_dungeon.png" alt="dungeon"><span>Grotte Hesque</span></span>1️⃣ (<span data-type="custom-tag" data-id="7754" class="tag-item" id="2502" type="item" name="Dofus Ocre" imageurl="https://api.dofusdb.fr/img/items/23012.png" dofusdbid="7754"><img src="https://api.dofusdb.fr/img/items/23012.png" alt="item"><span>Dofus Ocre</span></span>).</p></div><div data-type="quest-block" class="quest-block" title="Donjon magistral" questid="625" questname="Donjon magistral" status="in_progress"><p><span style="color: rgb(98, 172, 255);">Allez en</span> [1,-15] et parlez à <span style="color: rgb(255, 255, 0);">Emma Tompouce</span>.</p></div><div data-type="quest-block" class="quest-block" title="Donjon magistral" questid="625" questname="Donjon magistral" status="end"><p>Ensuite <span style="color: rgb(98, 172, 255);">allez</span> <span style="color: rgb(98, 172, 255);">en</span> [2,-1], <span style="color: rgb(98, 172, 255);">entrez</span> au<span style="color: rgb(98, 172, 255);"> milieu </span><span style="color: rgb(255, 255, 255);">e</span>t prenez la <span style="color: rgb(98, 172, 255);">porte de gauche</span> <span style="color: rgb(255, 255, 255);">puis</span> parlez à <span style="color: rgb(255, 255, 0);">Alain Deix</span> <span style="color: rgb(255, 255, 255);">pour finir </span><span data-type="custom-tag" data-id="899" class="tag-quest" id="625" type="quest" name="Donjon magistral" imageurl="https://ganymede-dofus.com/images/icon_quest.png" dofusdbid="899"><img src="https://ganymede-dofus.com/images/icon_quest.png" alt="quest"><span>Donjon magistral</span></span>.</p></div><div data-type="quest-block" class="quest-block" title="Entre quatre blops" questid="1948" questname="Entre quatre blops" status="start"><p><span style="color: rgb(255, 255, 0);">Continuez </span>de lui <span style="color: rgb(255, 255, 0);">parler </span>pour lancer <span data-type="custom-tag" data-id="2505" class="tag-quest" id="1948" type="quest" name="Entre quatre blops" imageurl="https://ganymede-dofus.com/images/icon_quest.png" dofusdbid="2505"><img src="https://ganymede-dofus.com/images/icon_quest.png" alt="quest"><span>Entre quatre blops</span></span>.</p></div><p><span style="color: rgb(5, 160, 69);">Astuce :</span></p><p>1️⃣ Quand le <span data-type="custom-tag" data-id="1027" class="tag-monster" id="565" type="monster" name="Corailleur Magistral" imageurl="https://api.dofusdb.fr/img/monsters/563.png" dofusdbid="1027"><img src="https://api.dofusdb.fr/img/monsters/563.png" alt="monster"><span>Corailleur Magistral</span></span> est sous l''effet "<span style="color: rgb(255, 255, 0);">Coraillement Magistral</span>" alors celui-ci <span style="color: rgb(255, 255, 0);">OS </span>au <span style="color: rgb(255, 255, 0);">CAC</span>.</p>', 23, '[GP23] Justiciers et plus', NULL, '#8b5cf6', 220, 1120, false, '{}', 29, '2026-05-02 12:06:58.068', '2026-05-02 12:06:58.068');
INSERT INTO public."GuideMilestone" VALUES ('cmooaqqlf002aygogi4yo6s1w', 'cmolc84qt0000noogp0gr4sjj', 'PREREQUIS', '👉 Étape bonus 👈', NULL, '<p style="text-align: center;"><span style="color: rgb(5, 160, 69);"><strong>👉 Étape bonus 👈</strong></span></p><p style="text-align: center;">🥩 Chasseur 50 à 60 🥩</p><p style="text-align: center;">🌽 Paysan/Alchimiste 30 à 40 🌽</p><p>Continuez de <span style="color: rgb(255, 255, 0);">monter </span>votre <span style="color: rgb(255, 255, 0);">métier </span>jusqu''au <span style="color: rgb(255, 255, 0);">niveau 40</span>.</p><p><span style="color: rgb(255, 255, 0);">Récupérez </span>de l''<span data-type="custom-tag" data-id="400" class="tag-item" id="168" type="item" name="Orge" imageurl="https://api.dofusdb.fr/img/items/34082.png" dofusdbid="400"><img src="https://api.dofusdb.fr/img/items/34082.png" alt="item"><span>Orge</span></span> et/ou <span style="color: rgb(255, 255, 0);">fabriquez </span>des <span data-type="custom-tag" data-id="524" class="tag-item" id="252" type="item" name="Fougasse" imageurl="https://api.dofusdb.fr/img/items/33018.png" dofusdbid="524"><img src="https://api.dofusdb.fr/img/items/33018.png" alt="item"><span>Fougasse</span></span> si vous êtes <span style="color: rgb(255, 255, 0);">paysan</span>.</p><p style="text-align: left;"><span style="color: rgb(255, 255, 0);">Récupérez </span>des <span data-type="custom-tag" data-id="428" class="tag-item" id="193" type="item" name="Sauge" imageurl="https://api.dofusdb.fr/img/items/36643.png" dofusdbid="428"><img src="https://api.dofusdb.fr/img/items/36643.png" alt="item"><span>Sauge</span></span> et/ou <span style="color: rgb(255, 255, 0);">fabriquez </span>des <span data-type="custom-tag" data-id="16404" class="tag-item" id="9422" type="item" name="Potion Raide Dite" imageurl="https://api.dofusdb.fr/img/items/12750.png" dofusdbid="16404"><img src="https://api.dofusdb.fr/img/items/12750.png" alt="item"><span>Potion Raide Dite</span></span> si vous êtes <span style="color: rgb(255, 255, 0);">alchimiste</span>.</p><p style="text-align: center;">🥩 Chasseur 50 à 60 🥩</p><p style="text-align: left;">Pour monter le métier <span style="color: rgb(255, 255, 0);">chasseur niveau 60</span>, prévoyez :</p><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p style="text-align: left;">171 <span data-type="custom-tag" data-id="17130" class="tag-item" id="9966" type="item" name="Viande Tendre" imageurl="https://api.dofusdb.fr/img/items/63483.png" dofusdbid="17130"><img src="https://api.dofusdb.fr/img/items/63483.png" alt="item"><span>Viande Tendre</span></span>1️⃣</p></div></li><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p style="text-align: left;">171 <span data-type="custom-tag" data-id="400" class="tag-item" id="168" type="item" name="Orge" imageurl="https://api.dofusdb.fr/img/items/34082.png" dofusdbid="400"><img src="https://api.dofusdb.fr/img/items/34082.png" alt="item"><span>Orge</span></span></p></div></li><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p style="text-align: left;">171 <span data-type="custom-tag" data-id="1974" class="tag-item" id="981" type="item" name="Feuille de salace" imageurl="https://api.dofusdb.fr/img/items/68376.png" dofusdbid="1974"><img src="https://api.dofusdb.fr/img/items/68376.png" alt="item"><span>Feuille de salace</span></span> (ou 18 <span data-type="custom-tag" data-id="16826" class="tag-item" id="9691" type="item" name="Sachet de Feuilles de salace" imageurl="https://api.dofusdb.fr/img/items/180006.png" dofusdbid="16826"><img src="https://api.dofusdb.fr/img/items/180006.png" alt="item"><span>Sachet de Feuilles de salace</span></span>)</p></div></li></ul><p>Ensuite <span style="color: rgb(255, 255, 0);">fabriquez </span>des <span data-type="custom-tag" data-id="17175" class="tag-item" id="10011" type="item" name="Salade Sufokienne" imageurl="https://api.dofusdb.fr/img/items/69816.png" dofusdbid="17175"><img src="https://api.dofusdb.fr/img/items/69816.png" alt="item"><span>Salade Sufokienne</span></span><span style="color: rgb(255, 255, 255);">.</span></p><p><span style="color: rgb(5, 160, 69);">Astuces :</span></p><p>1️⃣ Dans l''<span style="color: rgb(255, 255, 0);">encyclopédie</span> (touche "<span style="color: rgb(255, 255, 0);">b</span>"), <span style="color: rgb(255, 255, 0);">recherchez </span>dans les <span style="color: rgb(255, 255, 0);">ressources </span>la <span data-type="custom-tag" data-id="17130" class="tag-item" id="9966" type="item" name="Viande Tendre" imageurl="https://api.dofusdb.fr/img/items/63483.png" dofusdbid="17130"><img src="https://api.dofusdb.fr/img/items/63483.png" alt="item"><span>Viande Tendre</span></span>.</p><p>Ensuite faites <span style="color: rgb(255, 255, 255);">un</span> <span style="color: rgb(255, 255, 0);">clic droit </span><span style="color: rgb(255, 255, 255);">sur celle-ci</span><span style="color: rgb(255, 255, 0);"> </span>puis <span style="color: rgb(255, 255, 0);">Bestiaire </span>pour voir sur<span style="color: rgb(255, 255, 0);"> quels monstres l''obtenir</span> ainsi que le <span style="color: rgb(255, 255, 0);">taux de drop</span>.</p>', 0, 'Introduction', NULL, '#a855f7', 440, 1120, true, '{}', 30, '2026-05-02 12:06:58.084', '2026-05-02 12:06:58.084');
INSERT INTO public."GuideMilestone" VALUES ('cmooaqqll002bygogo8sxsewd', 'cmolc84qt0000noogp0gr4sjj', 'DONJON', 'Tour du Monde et Alignement.', NULL, '<p><span style="color: rgb(250, 0, 0);">Objectifs : </span>Tour du Monde et Alignement.</p><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p><span style="color: rgb(255, 255, 255);">Si vous êtes </span><span style="color: rgb(98, 172, 255);">bontarien</span>,<span style="color: rgb(100, 181, 246);"> </span><span style="color: rgb(255, 255, 0);">reprenez </span><span style="color: rgb(255, 255, 255);">le guide </span><span data-type="guide-step" class="guide-step" guideid="516" stepid="0" stepnumber="1" guidename="[GP9] ALIGNEMENT BONTARIEN" label="[GP9] Alignement Bontarien" baseurl="https://ganymede-dofus.com"><img src="https://ganymede-dofus.com/images/texteditor/guides.png" alt="GuideStep">[GP9] Alignement Bontarien</span> de l''<span style="color: rgb(255, 255, 0);">étape 37&nbsp;</span>jusqu''à l''<span style="color: rgb(255, 255, 0);">étape 67</span> incluse.</p></div></li></ul><div data-type="quest-block" class="quest-block" title="Entre quatre blops" questid="1948" questname="Entre quatre blops" status="in_progress"><p><span style="color: rgb(255, 255, 0);">Réalisez </span>le <span data-type="custom-tag" data-id="11" class="tag-dungeon" id="9" type="dungeon" name="Clos des Blops" imageurl="https://ganymede-dofus.com/images/icon_dungeon.png" dofusdbid="11"><img src="https://ganymede-dofus.com/images/icon_dungeon.png" alt="dungeon"><span>Clos des Blops</span></span>1️⃣2️⃣.</p></div><div data-type="quest-block" class="quest-block" title="Entre quatre blops" questid="1948" questname="Entre quatre blops" status="end"><p><span style="color: rgb(98, 172, 255);">Allez en</span> [2,-1], <span style="color: rgb(98, 172, 255);">entrez </span><span style="color: rgb(255, 255, 255);">au </span><span style="color: rgb(98, 172, 255);">milieu </span><span style="color: 