INSERT INTO public."GuideMilestone" VALUES ('cmooaqqor002vygogcbmmz6g8', 'cmolc84qt0000noogp0gr4sjj', 'DONJON', 'Krosmoz, Sidimote 1 et Alignement.', NULL, '<p><span style="color: rgb(250, 0, 0);">Objectifs :</span> Krosmoz, Sidimote 1 et Alignement.</p><p><span style="color: rgb(250, 0, 0);">Lisez bien toute l''étape avant de la faire, il y a pas mal d''action à faire !</span></p><p>Pour cette étape, <span style="color: rgb(255, 255, 0);">avancez </span>les <span style="color: rgb(255, 255, 0);">3 guides </span>jusqu''à atteindre <span data-type="custom-tag" data-id="35" class="tag-dungeon" id="27" type="dungeon" name="Laboratoire de Brumen Tinctorias" imageurl="https://ganymede-app.com/images/icon_dungeon.png" dofusdbid="35"><img src="https://ganymede-app.com/images/icon_dungeon.png" alt="dungeon"><span>Laboratoire de Brumen Tinctorias</span></span>.</p><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p><span style="color: rgb(255, 255, 255);">Si vous êtes </span><span style="color: rgb(98, 172, 255);">bontarien</span>, <span style="color: rgb(255, 255, 0);">reprenez </span><span style="color: rgb(255, 255, 255);">le guide </span><span data-type="guide-step" class="guide-step" guideid="516" stepid="0" stepnumber="1" guidename="[GP9] ALIGNEMENT BONTARIEN" label="[GP9] Alignement Bontarien" baseurl="https://ganymede-dofus.com"><img src="https://ganymede-dofus.com/images/texteditor/guides.png" alt="GuideStep">[GP9] Alignement Bontarien</span> de l''<span style="color: rgb(255, 255, 0);">étape 97&nbsp;</span>jusqu''à l''<span style="color: rgb(255, 255, 0);">étape 134</span>.</p></div></li></ul><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p><span style="color: rgb(255, 255, 255);">Si vous êtes</span><span style="color: rgb(100, 181, 246);"> </span><span style="color: rgb(235, 65, 101);">brâkmarien</span>, <span style="color: rgb(255, 255, 0);">reprenez </span><span style="color: rgb(255, 255, 255);">le guide </span><span data-type="guide-step" class="guide-step" guideid="773" stepid="0" stepnumber="1" guidename="[GP9] ALIGNEMENT BRÂKMARIEN" label="[GP9] Alignement Brâkmarien" baseurl="https://ganymede-dofus.com"><img src="https://ganymede-dofus.com/images/texteditor/guides.png" alt="GuideStep">[GP9] Alignement Brâkmarien</span> de l''<span style="color: rgb(255, 255, 0);">étape 85&nbsp;</span>jusqu''à l''<span style="color: rgb(255, 255, 0);">étape 104</span>.</p></div></li></ul><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p><span style="color: rgb(255, 255, 0);">Terminez </span>le guide<span data-type="guide-step" class="guide-step" guideid="374" stepid="0" stepnumber="1" guidename="[GP2] Krosmoz" label="[GP2] Krosmoz" baseurl="https://ganymede-dofus.com"><img src="https://ganymede-dofus.com/images/texteditor/guides.png" alt="GuideStep">[GP2] Krosmoz</span> depuis l''<span style="color: rgb(255, 255, 0);">étape 34</span>, <span style="color: rgb(255, 255, 0);">prévoyez </span>uniquement la <span data-type="custom-tag" data-id="281" class="tag-item" id="69" type="item" name="Pomme" imageurl="https://api.dofusdb.fr/img/items/42001.png" dofusdbid="281"><img src="https://api.dofusdb.fr/img/items/42001.png" alt="item"><span>Pomme</span></span> en<span style="color: rgb(255, 255, 0);"> fin d''étape</span>.</p></div></li></ul><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p><span style="color: rgb(255, 255, 0);">Commencez </span>et <span style="color: rgb(255, 255, 0);">terminez </span>le guide <span data-type="guide-step" class="guide-step" guideid="306" stepid="0" stepnumber="1" guidename="[GP16] Sidimote 1 : Les landes mortes" label="[GP16] Sidimote 1 : Les landes mortes" baseurl="https://ganymede-dofus.com"><img src="https://ganymede-dofus.com/images/texteditor/guides.png" alt="GuideStep">[GP16] Sidimote 1 : Les landes mortes</span>1️⃣.</p></div></li></ul><div data-type="quest-block" class="quest-block" title="Histoire de chiens" questid="634" questname="Histoire de chiens" status="in_progress"><p><span style="color: rgb(255, 255, 0);">Réalisez </span>le <span data-type="custom-tag" data-id="35" class="tag-dungeon" id="27" type="dungeon" name="Laboratoire de Brumen Tinctorias" imageurl="https://ganymede-app.com/images/icon_dungeon.png" dofusdbid="35"><img src="https://ganymede-app.com/images/icon_dungeon.png" alt="dungeon"><span>Laboratoire de Brumen Tinctorias</span></span>2️⃣ et</p></div><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p><span style="color: rgb(255, 255, 0);">Capturez </span>le <span data-type="custom-tag" data-id="3100" class="tag-monster" id="1232" type="monster" name="Nelween" imageurl="https://api.dofusdb.fr/img/monsters/856.png" dofusdbid="3100"><img src="https://api.dofusdb.fr/img/monsters/856.png" alt="monster"><span>Nelween</span></span> pour le guide <span data-type="guide-step" class="guide-step" guideid="66" stepid="0" stepnumber="1" guidename="[GP19] DOFUS EMERAUDE" label="[GP19] DOFUS EMERAUDE" baseurl="https://ganymede-dofus.com"><img src="https://ganymede-dofus.com/images/texteditor/guides.png" alt="GuideStep">[GP19] DOFUS EMERAUDE</span>3️⃣.</p></div></li></ul><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p><span style="color: rgb(255, 255, 255);">Si vous êtes </span><span style="color: rgb(98, 172, 255);">bontarien</span>,&nbsp;<span style="color: rgb(255, 255, 0);">cliquez </span>sur le <span style="color: rgb(255, 255, 0);">tube phosphorescent</span> à la <span style="color: rgb(98, 172, 255);">fin du donjon</span>.</p></div></li></ul><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p><span style="color: rgb(255, 255, 255);">Si vous êtes</span><span style="