INSERT INTO public."GuideMilestone" VALUES ('cmooaqqpp0030ygog4nt3xzex', 'cmolc84qt0000noogp0gr4sjj', 'PREREQUIS', '👉 Étape bonus 👈', NULL, '<p style="text-align: center;"><span style="color: rgb(5, 160, 69);"><strong>👉 Étape bonus 👈</strong></span></p><p style="text-align: center;">🗡️ Mise à jour de l''équipement 🗡️</p><p style="text-align: left;">Pour la tranche de <span style="color: rgb(255, 255, 0);">niveau 60-80</span>, les <span style="color: rgb(255, 255, 0);">équipements </span>ont pour <span style="color: rgb(255, 255, 0);">base </span>la <span style="color: rgb(255, 255, 0);">Panoplie Blop Royale</span>.</p><p style="text-align: left;">Vous trouverez <span style="color: rgb(255, 255, 0);">2 versions</span> pour <span style="color: rgb(255, 255, 0);">chaque élément</span>.</p><p style="text-align: left;">La première en <span style="color: rgb(255, 255, 0);">10 PA</span> nécessite<span style="color: rgb(255, 255, 0);"> peu d''FM</span> et a un peu <span style="color: rgb(255, 255, 0);">plus de dégât</span>.</p><p style="text-align: left;">La seconde en <span style="color: rgb(255, 255, 0);">11 PA</span> vous offre la possibilité d''avoir <span style="color: rgb(255, 255, 0);">plusieurs over vitalité</span>.</p><p style="text-align: left;">Voici la <span style="color: rgb(255, 255, 0);">liste </span>des <span style="color: rgb(255, 255, 0);">équipements1️⃣2️⃣ </span>:</p><p style="text-align: left;">(On a un soucis avec les liens pour les stuffs 11 PA)</p><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p>10 PA : <a target="_blank" rel="noopener noreferrer nofollow" href="https://www.dofusbook.net/fr/equipement/5768631-60-80-terre/objets"><span style="color: rgb(115, 67, 9);">Terre</span></a> ou 11 PA : <a target="_blank" rel="noopener noreferrer nofollow" href="https://www.dofusbook.net/fr/equipement/17727989-db/objets"><span style="color: rgb(115, 67, 9);">Terre</span></a>.</p></div></li><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p>10 PA : <a target="_blank" rel="noopener noreferrer nofollow" href="https://www.dofusbook.net/fr/equipement/5768671-80-eau/objets"><span style="color: rgb(66, 165, 246);">Eau</span></a> ou 11 PA : <a target="_blank" rel="noopener noreferrer nofollow" href="https://www.dofusbook.net/fr/equipement/17725209-db/objets"><span style="color: rgb(98, 172, 255);">Eau</span></a>.</p></div></li><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p>10 PA : <a target="_blank" rel="noopener noreferrer nofollow" href="https://www.dofusbook.net/fr/equipement/5768597-60-80-feu/objets"><span style="color: rgb(235, 65, 101);">Feu</span></a> ou 11 PA : <a target="_blank" rel="noopener noreferrer nofollow" href="https://www.dofusbook.net/fr/equipement/17727959-db/objets"><span style="color: rgb(235, 65, 101);">Feu</span></a>.</p></div></li><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p>10 PA : <a target="_blank" rel="noopener noreferrer nofollow" href="https://www.dofusbook.net/fr/equipement/5768693-60-80-air/objets"><span style="color: rgb(131, 198, 131);">Air</span></a> ou 11 PA : <a target="_blank" rel="noopener noreferrer nofollow" href="https://www.dofusbook.net/fr/equipement/17727924-db/objets"><span style="color: rgb(131, 198, 131);">Air</span></a>.</p></div></li></ul><p><span style="color: rgb(5, 160, 69);">Astuces :</span></p><p>1️⃣ <span style="color: rgb(255, 255, 255);">Pensez à </span><span style="color: rgb(255, 255, 0);">FM </span><span style="color: rgb(255, 255, 255);">votre </span><span style="color: rgb(255, 255, 0);">arme </span><span style="color: rgb(255, 255, 255);">avec </span>une <span data-type="custom-tag" data-id="10057" class="tag-item" id="4249" type="item" name="Rune de chasse" imageurl="https://api.dofusdb.fr/img/items/78059.png" dofusdbid="10057"><img src="https://api.dofusdb.fr/img/items/78059.png" alt="item"><span>Rune de chasse</span></span> si vous êtes <span style="color: rgb(255, 255, 0);">chasseur</span>.</p><p>2️⃣ Pour voir la liste des <span style="color: rgb(255, 255, 0);">ingrédients nécessaires </span><span style="color: rgb(255, 255, 255);">à la fabrication complète de l''équipement</span>, utilisez les <span style="color: rgb(255, 255, 0);">liens DofusBook </span>ci-dessus puis :</p><p><span style="color: rgb(255, 255, 0);">Cliquez </span>sur <span style="color: rgb(255, 255, 0);">Détails du craft de ce stuff </span>(logo d''un marteau)<span style="color: rgb(255, 255, 0);"> </span>et <span style="color: rgb(255, 255, 0);">sélectionnez </span>les <span style="color: rgb(255, 255, 0);">items </span>à <span style="color: rgb(255, 255, 0);">fabriquer</span>.</p>', 0, 'Introduction', NULL, '#a855f7', 220, 1600, true, '{}', 41, '2026-05-02 12:06:58.237', '2026-05-02 12:06:58.237');
INSERT INTO public."GuideMilestone" VALUES ('cmooaqqpw0031ygogza77fe7p', 'cmolc84qt0000noogp0gr4sjj', 'PREREQUIS', '👉 Étape bonus 👈', NULL, '<p style="text-align: center;"><span style="color: rgb(5, 160, 69);"><strong>👉 Étape bonus 👈</strong></span></p><p style="text-align: center;">🥩 Chasseur 70 à 80 🥩</p><p style="text-align: center;">🌽 Paysan/Alchimiste 50 à 60 🌽</p><p>Continuez de <span style="color: rgb(255, 255, 0);">monter </span>votre <span style="color: rgb(255, 255, 0);">métier </span>jusqu''au <span style="color: rgb(255, 255, 0);">niveau 60</span>.</p><p><span style="color: rgb(255, 255, 0);">Récupérez </span>de l''<span data-type="custom-tag" data-id="533" class="tag-item" id="257" type="item" name="Avoine" imageurl="https://api.dofusdb.fr/img/items/34154.png" dofusdbid="533"><img src="https://api.dofusdb.fr/img/items/34154.png" alt="item"><span>Avoine</span></span> et/ou <span style="color: rgb(255, 255, 0);">fabriquez </span>des <span data-type="custom-tag" data-id="16431" class="tag-item" id="9439" type="item" name="Pain de Mie" imageurl="https://api.dofusdb.fr/img/items/33074.png" dofusdbid="16431"><img src="https://api.dofusdb.fr/img/items/33074.png" alt="item"><span>Pain de Mie</span></span> si vous êtes <span style="color: rgb(255, 255, 0);">paysan</span>.</p><p style="text-align: left;"><span style="color: rgb(255, 255, 0);">Récupérez </span>des <span data-type="custom-tag" data-id="395" class="tag-item" id="163" type="item" name="Trèfle à 5 feuilles" imageurl="https://api.dofusdb.fr/img/items/36067.png" dofusdbid="395"><img src="https://api.dofusdb.fr/img/items/36067.png" alt="item"><span>Trèfle à 5 feuilles</span></span> et/ou <span style="color: rgb(255, 255, 0);">fabriquez </span>des <span data-type="custom-tag" data-id="580" class="tag-item" id="268" type="item" name="Potion Ghetto Raide" imageurl="https://api.dofusdb.fr/img/items/12018.png" dofusdbid="580"><img src="https://api.dofusdb.fr/img/items/12018.png" alt="item"><span>Potion Ghetto Raide</span></span> si vous êtes <span style="color: rgb(255, 255, 0);">alchimiste</span>.</p><p style="text-align: center;">🥩 Chasseur 70 à 80 🥩</p><p style="text-align: left;">Pour monter le métier <span style="color: rgb(255, 255, 0);">chasseur niveau 80</span>, prévoyez :</p><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p style="text-align: left;">166 <span data-type="custom-tag" data-id="17134" class="tag-item" id="9970" type="item" name="Viande Avariée" imageurl="https://api.dofusdb.fr/img/items/63426.png" dofusdbid="17134"><img src="https://api.dofusdb.fr/img/items/63426.png" alt="item"><span>Viande Avariée</span></span></p></div></li><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p style="text-align: left;">166 <span data-type="custom-tag" data-id="533" class="tag-item" id="257" type="item" name="Avoine" imageurl="https://api.dofusdb.fr/img/items/34154.png" dofusdbid="533"><img src="https://api.dofusdb.fr/img/items/34154.png" alt="item"><span>Avoine</span></span></p></div></li><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p style="text-align: left;">166 <span data-type="custom-tag" data-id="1975" class="tag-item" id="982" type="item" name="Oignon" imageurl="https://api.dofusdb.fr/img/items/68377.png" dofusdbid="1975"><img src="https://api.dofusdb.fr/img/items/68377.png" alt="item"><span>Oignon</span></span> (ou 17 <span data-type="custom-tag" data-id="16832" class="tag-item" id="9697" type="item" name="Sachet d''Oignons" imageurl="https://api.dofusdb.fr/img/items/180011.png" dofusdbid="16832"><img src="https://api.dofusdb.fr/img/items/180011.png" alt="item"><span>Sachet d''Oignons</span></span>)</p></div></li></ul><p>Ensuite <span style="color: rgb(255, 255, 0);">fabriquez </span>des <span data-type="custom-tag" data-id="17179" class="tag-item" id="10015" type="item" name="Parmentier à l''Oignon" imageurl="https://api.dofusdb.fr/img/items/69758.png" dofusdbid="17179"><img src="https://api.dofusdb.fr/img/items/69758.png" alt="item"><span>Parmentier à l''Oignon</span></span><span style="color: rgb(255, 255, 255);">.</span></p>', 0, 'Introduction', NULL, '#a855f7', 440, 1600, true, '{}', 42, '2026-05-02 12:06:58.244', '2026-05-02 12:06:58.244');
INSERT INTO public."GuideMilestone" VALUES ('cmooaqqq20032ygogoeqy55ra', 'cmolc84qt0000noogp0gr4sjj', 'DONJON', 'Saharach 1 et Tour du Monde.', NULL, '<p><span style="color: rgb(250, 0, 0);">Objectifs : </span>Saharach 1 et Tour du Monde.</p><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p>(<span style="color: rgb(170, 71, 188);">Optionnel</span>) <span style="color: rgb(255, 255, 0);">Commencez </span>et <span style="color: rgb(255, 255, 0);">terminez </span>le guide <span data-type="guide-step" class="guide-step" guideid="65" stepid="0" stepnumber="1" guidename="[GP17] Saharach 1" label="[GP17] Saharach 1" baseurl="https://ganymede-dofus.com"><img src="https://ganymede-dofus.com/images/texteditor/guides.png" alt="GuideStep">[GP17] Saharach 1</span>.</p></div></li></ul><div data-type="quest-block" class="quest-block" title="Le fossile et le marteau" questid="635" questname="Le fossile et le marteau" status="in_progress"><p><span style="color: rgb(255, 255, 0);">Réalisez </span>le <span data-type="custom-tag" data-id="100" class="tag-dungeon" id="87" type="dungeon" name="Cimetière des Mastodontes" imageurl="https://ganymede-dofus.com/images/icon_dungeon.png" dofusdbid="100"><img src="https://ganymede-dofus.com/images/icon_dungeon.png" alt="dungeon"><span>Cimetière des Mastodontes</span></span>1️⃣2️⃣.</p></div><div data-type="quest-block" class="quest-block" title="Le fossile et le marteau" questid="635" questname="Le fossile et le marteau" status="end"><p><span style="color: rgb(98, 172, 255);">Allez en</span> [-16,2] (<span style="color: rgb(98, 172, 255);">Zaap </span>des <span style="color: rgb(98, 172, 255);">Eleveurs</span>) et parlez à <span style="color: rgb(255, 255, 0);">Thelma Geur</span> pour finir <span data-type="custom-tag" data-id="909" class="tag-quest" id="635" type="quest" name="Le fossile et le marteau" imageurl="https://ganymede-dofus.com/images/icon_quest.png" dofusdbid="909"><img src="ht