INSERT INTO public."GuideMilestone" VALUES ('cmooaqqsz003jygog6up8aolg', 'cmolc84qt0000noogp0gr4sjj', 'PREREQUIS', '👉 Étape bonus 👈', NULL, '<p style="text-align: center;"><span style="color: rgb(5, 160, 69);"><strong>👉 Étape bonus 👈</strong></span></p><p style="text-align: center;">🥩 Chasseur 90 à 100 🥩</p><p style="text-align: center;">🌽 Paysan/Alchimiste 70 à 80 🌽</p><p>Continuez de <span style="color: rgb(255, 255, 0);">monter </span>votre <span style="color: rgb(255, 255, 0);">métier </span>jusqu''au <span style="color: rgb(255, 255, 0);">niveau 80</span>.</p><p><span style="color: rgb(255, 255, 0);">Récupérez </span>de l''<span data-type="custom-tag" data-id="401" class="tag-item" id="169" type="item" name="Houblon" imageurl="https://api.dofusdb.fr/img/items/34080.png" dofusdbid="401"><img src="https://api.dofusdb.fr/img/items/34080.png" alt="item"><span>Houblon</span></span> et/ou <span style="color: rgb(255, 255, 0);">fabriquez </span>des <span data-type="custom-tag" data-id="692" class="tag-item" id="312" type="item" name="Pain Consistant" imageurl="https://api.dofusdb.fr/img/items/33012.png" dofusdbid="692"><img src="https://api.dofusdb.fr/img/items/33012.png" alt="item"><span>Pain Consistant</span></span> si vous êtes <span style="color: rgb(255, 255, 0);">paysan</span>.</p><p style="text-align: left;"><span style="color: rgb(255, 255, 0);">Récupérez </span>des <span data-type="custom-tag" data-id="395" class="tag-item" id="163" type="item" name="Trèfle à 5 feuilles" imageurl="https://api.dofusdb.fr/img/items/36067.png" dofusdbid="395"><img src="https://api.dofusdb.fr/img/items/36067.png" alt="item"><span>Trèfle à 5 feuilles</span></span> et/ou <span style="color: rgb(255, 255, 0);">fabriquez </span>des <span data-type="custom-tag" data-id="1712" class="tag-item" id="825" type="item" name="Potion Pahoa Raide" imageurl="https://api.dofusdb.fr/img/items/12140.png" dofusdbid="1712"><img src="https://api.dofusdb.fr/img/items/12140.png" alt="item"><span>Potion Pahoa Raide</span></span> si vous êtes <span style="color: rgb(255, 255, 0);">alchimiste</span>.</p><p style="text-align: center;">🥩 Chasseur 90 à 100 🥩</p><p style="text-align: left;">Pour monter le métier <span style="color: rgb(255, 255, 0);">chasseur niveau 100</span>, prévoyez :</p><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p style="text-align: left;">163 <span data-type="custom-tag" data-id="17138" class="tag-item" id="9974" type="item" name="Viande Rassie" imageurl="https://api.dofusdb.fr/img/items/63473.png" dofusdbid="17138"><img src="https://api.dofusdb.fr/img/items/63473.png" alt="item"><span>Viande Rassie</span></span></p></div></li><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p style="text-align: left;">163 <span data-type="custom-tag" data-id="401" class="tag-item" id="169" type="item" name="Houblon" imageurl="https://api.dofusdb.fr/img/items/34080.png" dofusdbid="401"><img src="https://api.dofusdb.fr/img/items/34080.png" alt="item"><span>Houblon</span></span></p></div></li><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p style="text-align: left;">163 <span data-type="custom-tag" data-id="1731" class="tag-item" id="842" type="item" name="Dose de jus goûtu" imageurl="https://api.dofusdb.fr/img/items/15262.png" dofusdbid="1731"><img src="https://api.dofusdb.fr/img/items/15262.png" alt="item"><span>Dose de jus goûtu</span></span> (ou 17 <span data-type="custom-tag" data-id="16823" class="tag-item" id="9688" type="item" name="Tonneau de Jus Goûtu" imageurl="https://api.dofusdb.fr/img/items/180015.png" dofusdbid="16823"><img src="https://api.dofusdb.fr/img/items/180015.png" alt="item"><span>Tonneau de Jus Goûtu</span></span>)</p></div></li></ul><p>Ensuite <span style="color: rgb(255, 255, 0);">fabriquez </span>des <span data-type="custom-tag" data-id="17183" class="tag-item" id="10019" type="item" name="Pot-au-feu Goûteux" imageurl="https://api.dofusdb.fr/img/items/69806.png" dofusdbid="17183"><img src="https://api.dofusdb.fr/img/items/69806.png" alt="item"><span>Pot-au-feu Goûteux</span></span><span style="color: rgb(255, 255, 255);">.</span></p>', 0, 'Introduction', NULL, '#a855f7', 440, 1920, true, '{}', 50, '2026-05-02 12:06:58.356', '2026-05-02 12:06:58.356');
INSERT INTO public."GuideMilestone" VALUES ('cmooaqqt5003kygog2jlxyfku', 'cmolc84qt0000noogp0gr4sjj', 'DOFUS', 'DOFUS DES VEILLEURS', NULL, '<p><span style="color: rgb(250, 0, 0);">Objectifs :</span> <span data-type="custom-tag" data-id="16061" class="tag-item" id="9168" type="item" name="Dofus des Veilleurs" imageurl="https://api.dofusdb.fr/img/items/23020.png" dofusdbid="16061"><img src="https://api.dofusdb.fr/img/items/23020.png" alt="item"><span>Dofus des Veilleurs</span></span> et Prérequis du <span data-type="custom-tag" data-id="8698" class="tag-item" id="3232" type="item" name="Dofus Nébuleux" imageurl="https://api.dofusdb.fr/img/items/23016.png" dofusdbid="8698"><img src="https://api.dofusdb.fr/img/items/23016.png" alt="item"><span>Dofus Nébuleux</span></span>.</p><p><span style="color: rgb(250, 0, 0);">Lisez bien toute l''étape avant de la faire !</span></p><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p><span style="color: rgb(255, 255, 0);">Commencez </span>le guide <span data-type="guide-step" class="guide-step" guideid="62" stepid="0" stepnumber="1" guidename="[GP20] DOFUS DES VEILLEURS" label="[GP20] DOFUS DES VEILLEURS" baseurl="https://ganymede-dofus.com"><img src="https://ganymede-dofus.com/images/texteditor/guides.png" alt="GuideStep">[GP20] DOFUS DES VEILLEURS</span>1️⃣ jusqu''à l''<span style="color: rgb(255, 255, 0);">étape 48</span> <span style="color: rgb(250, 0, 0);">SANS</span> drop le <span data-type="custom-tag" data-id="16050" class="tag-item" id="9157" type="item" name="Diamant Dimensionnel" imageurl="https://api.dofusdb.fr/img/items/50025.png" dofusdbid="16050"><img src="https://api.dofusdb.fr/img/items/50025.png" alt="item"><span>Diamant Dimensionnel</span></span>.</p></div></li></ul><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p><span style="color: rgb(255, 255, 0);">Commencez </span>et <span style="color: rgb(255, 255, 0);">terminez </span>le guide <span data-type="guide-step" class="guide-step" guideid="431" stepid="0" stepnumber="1" guidename="[GP21] Enutrosor 1" label="[GP21] Enutrosor 1" baseurl="https://ganymede-dofus.com"><img src="https://ganymede-dofus.com/images/texteditor/guides.png" alt="GuideStep">[GP21] Enutrosor 1</span>.</p></div></li></ul><p><span style="color: rgb(255, 255, 0);">Réalisez</span> la <span data-type="custom-tag" data-id="77" class="tag-dungeon" id="65" type="dungeon" name="Fabrique de Malléfisk" imageurl="https://ganymede-app.com/images/icon_dungeon.png" dofusdbid="77"><img src="https://ganymede-app.com/images/icon_dungeon.png" alt="dungeon"><span>Fabrique de Malléfisk</span></span> et</p><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p>A l''<span style="color: rgb(255, 255, 0);">étape 28</span>, parlez aux <span style="color: rgb(255, 255, 0);">PNJ</span> à la<span style="color: rgb(98, 172, 255);"> fin du donjon</span>.</p></div></li></ul><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p><span style="color: rgb(255, 255, 0);">Terminez </span>le guide <span data-type="guide-step" class="guide-step" guideid="62" stepid="0" stepnumber="1" guidename="[GP20] DOFUS DES VEILLEURS" label="[GP20] DOFUS DES VEILLEURS" baseurl="https://ganymede-dofus.com"><img src="https://ganymede-dofus.com/images/texteditor/guides.png" alt="GuideStep">[GP20] DOFUS DES VEILLEURS</span>2️⃣3️⃣.</p></div></li></ul><p><span style="color: rgb(250, 0, 0);">Félicitation !</span> Vous <span style="color: rgb(255, 255, 0);">obtenez </span>le <span data-type="custom-tag" data-id="16061" class="tag-item" id="9168" type="item" name="Dofus des Veilleurs" imageurl="https://api.dofusdb.fr/img/items/23020.png" dofusdbid="16061"><img src="https://api.dofusdb.fr/img/items/23020.png" alt="item"><span>Dofus des Veilleurs</span></span>.</p><p><span style="color: rgb(5, 160, 69);">Astuces :</span></p><p>1️⃣ Il est <span style="color: rgb(255, 255, 0);">conseillé </span>de <span style="color: rgb(255, 255, 0);">bloquer </span>votre <span style="color: rgb(255, 255, 0);">XP</span> pour ne <span style="color: rgb(255, 255, 0);">pas dépasser</span> le <span style="color: rgb(255, 255, 0);">niveau 114</span>, si c''est <span style="color: rgb(255, 255, 0);">déjà le cas</span> pas de soucis vous ferez un <span style="color: rgb(255, 255, 0);">donjon différent</span>.</p><p>Pour <span style="color: rgb(255, 255, 0);">bloquer </span>votre <span style="color: rgb(255, 255, 0);">XP</span>, depuis l''interface <span style="color: rgb(255, 255, 0);">caractéristique</span>, cliquez sur le <span style="color: rgb(255, 255, 0);">bouton avec une flèche</span> à droite du montant d''expérience du prochain niveau.</p><p>2️⃣ Si vous avez <span style="color: rgb(255, 255, 0);">dépassé </span>le <span style="color: rgb(255, 255, 0);">niveau 114</span>, allez <span style="color: rgb(255, 255, 0);">drop </span>le <span data-type="custom-tag" data-id="16050" class="tag-item" id="9157" type="item" name="Diamant Dimensionnel" imageurl="https://api.dofusdb.fr/img/items/50025.png" dofusdbid="16050"><img src="https://api.dofusdb.fr/img/items/50025.png" alt="item"><span>Diamant Dimensionnel</span></span> sur l''un des <span style="color: rgb(255, 255, 0);">autres donjons </span>listés à l''<span style="color: rgb(255, 255, 0);">étape 48</span>.</p><p>3️⃣ Si vous <span style="color: rgb(255, 255, 0);">n''arrivez pas</span> à faire les <span style="color: rgb(255, 255, 0);">combats </span>dans le guide <span data-type="guide-step" class="guide-step" guideid="62" stepid="0" stepnumber="1" guidename="[GP20] DOFUS DES VEILLEURS" label="[GP20] DOFUS DES VEILLEURS" baseurl="https://ganymede-dofus.com"><img src="https://ganymede-dofus.com/images/texteditor/guides.png" alt="GuideStep">[GP20] DOFUS DES VEILLEURS</span> vous pourrez le finir plus tard.</p><p>Il n''est <span style="color: rgb(255, 255, 0);">pas requis</span> pour la suite <span style="color: rgb(255, 255, 0);">avant l''étape 75</span>, un rappel vous sera donné au moment voulu.</p>', 20, '[GP20] DOFUS DES VEILLEURS', NULL, '#f59e0b', 660, 1920, false, '{}', 51, '2026-05-02 12:06:58.361', '2026-05-02 12:06:58.361');
INSERT INTO public."GuideMilestone" VALUES ('cmooaqqto003nygogimnfm08g', 'cmolc84qt0000noogp0gr4sjj', 'DOFUS', 'Tour du Monde.', NULL, '<p><span style="color: rgb(250, 0, 0);">Objectif :</span> Tour du Monde.</p><div data-type="quest-block" class="quest-block" title="Tour d''honneur" questid="1953" questname="Tour d''honneur" status="in_progress"><p><span style="color: rgb(255, 255, 0);">Réalisez </span>le <span data-type="custom-tag" data-id="115" class="tag-dungeon" id="102" type="dungeon" name="Repaire du Kharnozor" imageurl="https://ganymede-dofus.com/images/icon_dungeon.png" dofusdbid="115"><img src="https://ganymede-dofus.com/images/icon_dungeon.png" alt="dungeon"><span>Repaire du Kharnozor</span></span>1️⃣.</p></div><div data-type="quest-block" class="quest-block" title="Tour d''honneur" questid="1953" questname="Tour d''honneur" status="end"><p><span style="color: rgb(98, 172, 255);">Allez en</span> [-45,19] (<span style="color: rgb(98, 172, 255);">Zaap </span>du <span style="color: rgb(98, 172, 255);">Village Côtier</span>) et parlez à <span style="color: rgb(255, 255, 0);">Anne Ullaire</span> pour finir <span data-type="custom-tag" data-id="2510" class="tag-quest" id="1953" type="quest" name="Tour d''honneur" imageurl="https://ganymede-dofus.com/images/icon_quest.png" dofusdbid="2510"><img src="https://ganymede-dofus.com/images/icon_quest.png" alt="quest"><span>Tour d''honneur</span></span>.</p></div><div data-type="quest-block" class="quest-block" title="Tour de marionnettes" questid="1143" questname="Tour de marionnettes" status="start"><p><span style="color: rgb(255, 255, 0);">Continuez </span>de lui <span style="color: rgb(255, 255, 0);">parler </span>pour lancer <span data-type="custom-tag" data-id="1432" class="tag-quest" id="1143" type="quest" name="Tour de marionnettes" imageurl="https://ganymede-dofus.com/images/icon_quest.png" dofusdbid="1432"><img src="https://ganymede-dofus.com/images/icon_quest.png" alt="quest"><span>Tour de marionnettes</span></span>.</p></div><p><span style="color: rgb(5, 160, 69);">Astuce :</span></p><p>1️⃣ Faites un <span style="color: rgb(255, 255, 0);">challenge </span>sur un <span data-type="custom-tag" data-id="5820" class="tag-monster" id="3572" type="monster" name="Dragoss Protéiforme" imageurl="https://api.dofusdb.fr/img/monsters/1912.png" dofusdbid="5820"><img src="https://api.dofusdb.fr/img/monsters/1912.png" alt="monster"><span>Dragoss Protéiforme</span></span>.</p>', 0, 'Introduction', NULL, '#f59e0b', 0, 1920, false, '{}', 52, '2026-05-02 12:06:58.38', '2026-05-02 12:06:58.38');
