INSERT INTO public."GuideMilestone" VALUES ('cmooaqrc6006mygogcc9r1a69', 'cmolc84qt0000noogp0gr4sjj', 'DOFUS', 'Tour du Monde,', NULL, '<p><span style="color: rgb(250, 0, 0);">Objectifs :</span> Tour du Monde, <span data-type="custom-tag" data-id="739" class="tag-item" id="345" type="item" name="Dofus Turquoise" imageurl="https://api.dofusdb.fr/img/items/23003.png" dofusdbid="739"><img src="https://api.dofusdb.fr/img/items/23003.png" alt="item"><span>Dofus Turquoise</span></span> et Otomaï 3.</p><div data-type="quest-block" class="quest-block" title="La voie du guerrier" questid="86" questname="La voie du guerrier" status="in_progress"><p><span style="color: rgb(255, 255, 0);">Réalisez </span><span style="color: rgb(255, 255, 255);">la </span><span data-type="custom-tag" data-id="53" class="tag-dungeon" id="44" type="dungeon" name="Salle du Minotot" imageurl="https://ganymede-dofus.com/images/icon_dungeon.png" dofusdbid="53"><img src="https://ganymede-dofus.com/images/icon_dungeon.png" alt="dungeon"><span>Salle du Minotot</span></span>1️⃣ (<span data-type="custom-tag" data-id="7754" class="tag-item" id="2502" type="item" name="Dofus Ocre" imageurl="https://api.dofusdb.fr/img/items/23012.png" dofusdbid="7754"><img src="https://api.dofusdb.fr/img/items/23012.png" alt="item"><span>Dofus Ocre</span></span>).</p></div><div data-type="quest-block" class="quest-block" title="La voie du guerrier" questid="86" questname="La voie du guerrier" status="in_progress"><p><span style="color: rgb(98, 172, 255);">Allez en</span> [-6,-37] e<span style="color: rgb(255, 255, 255);">t parlez au </span><span style="color: rgb(255, 255, 0);">Maître des clefs</span><span style="color: rgb(255, 255, 255);">.</span></p></div><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p>(<span style="color: rgb(170, 71, 188);">Optionnel</span>) <span style="color: rgb(255, 255, 0);">Commencez </span>et <span style="color: rgb(255, 255, 0);">terminez