INSERT INTO public."GuideMilestone" VALUES ('cmooaqrcz006rygogaqomh5kf', 'cmolc84qt0000noogp0gr4sjj', 'DOFUS', 'DDG-FRIGOST 1', NULL, '<p><span style="color: rgb(250, 0, 0);">Objectifs : </span><span data-type="custom-tag" data-id="7043" class="tag-item" id="2067" type="item" name="Dofus des Glaces" imageurl="https://api.dofusdb.fr/img/items/23005.png" dofusdbid="7043"><img src="https://api.dofusdb.fr/img/items/23005.png" alt="item"><span>Dofus des Glaces</span></span> - Partie 1 et <span data-type="custom-tag" data-id="739" class="tag-item" id="345" type="item" name="Dofus Turquoise" imageurl="https://api.dofusdb.fr/img/items/23003.png" dofusdbid="739"><img src="https://api.dofusdb.fr/img/items/23003.png" alt="item"><span>Dofus Turquoise</span></span>.</p><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p><span style="color: rgb(255, 255, 0);">Reprenez </span>le guide <span data-type="guide-step" class="guide-step" guideid="98" stepid="0" stepnumber="1" guidename="[GP30] DDG-FRIGOST 1" label="[GP30] DDG-FRIGOST 1 " baseurl="https://ganymede-dofus.com"><img src="https://ganymede-dofus.com/images/texteditor/guides.png" alt="GuideStep">[GP30] DDG-FRIGOST 1 </span>&nbsp;de l''<span style="color: rgb(255, 255, 0);">étape 108</span> jusqu''à l''<span style="color: rgb(255, 255, 0);">étape 153</span> incluse.</p></div></li></ul><p><span style="color: rgb(255, 255, 0);">Réalisez </span>l''<span data-type="custom-tag" data-id="57" class="tag-dungeon" id="48" type="dungeon" name="Hypogée de l''Obsidiantre" imageurl="https://ganymede-dofus.com/images/icon_dungeon.png" dofusdbid="57"><img src="https://ganymede-dofus.com/images/icon_dungeon.png" alt="dungeon"><span>Hypogée de l''Obsidiantre</span></span> avec l''<span data-type="custom-tag" data-id="28451" class="tag-item" id="18567" type="item" name="Idole de Thomahon d''Obsidienne" imageurl="https://api.dofusdb.fr/img/items/178114.png" dofusdbid="28451"><img src="https:/