INSERT INTO public."GuideMilestone" VALUES ('cmooaqrk8007yygogklxkrc3c', 'cmolc84qt0000noogp0gr4sjj', 'DONJON', 'Nimotopia et Justicier.', NULL, '<p><span style="color: rgb(250, 0, 0);">Objectifs :</span> Nimotopia et Justicier.</p><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p><span style="color: rgb(255, 255, 0);">Commencez </span>et <span style="color: rgb(255, 255, 0);">terminez </span>le guide&nbsp;<span data-type="guide-step" class="guide-step" guideid="354" stepid="0" stepnumber="1" guidename="[GP48] NIMOTOPIA" label="[GP48] NIMOTOPIA" baseurl="https://ganymede-dofus.com"><img src="https://ganymede-dofus.com/images/texteditor/guides.png" alt="GuideStep">[GP48] NIMOTOPIA</span><span style="color: rgb(255, 255, 255);">.</span></p></div></li></ul><p><span style="color: rgb(255, 255, 0);">Réalisez </span><span style="color: rgb(255, 255, 255);">le </span><span data-type="custom-tag" data-id="104" class="tag-dungeon" id="91" type="dungeon" name="Camp du Comte Razof" imageurl="https://ganymede-dofus.com/images/icon_dungeon.png" dofusdbid="104"><img src="https://ganymede-dofus.com/images/icon_dungeon.png" alt="dungeon"><span>Camp du Comte Razof</span></span>1️⃣ et&nbsp;</p><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p>A l''<span style="color: rgb(255, 255, 0);">étape 50</span>, parlez à la <span style="color: rgb(255, 255, 0);">Minikrone Effrayée</span> dans la <span style="color: rgb(98, 172, 255);">salle 5</span> puis faites les <span style="color: rgb(255, 255, 0);">tâches </span>à la <span style="color: rgb(98, 172, 255);">fin du donjon</span>.</p></div></li></ul><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p>(<span style="color: rgb(170, 71, 188);">Optionnel</span>)&nbsp;<span style="color: rgb(255, 255, 0);">Continuez </span>le guide <span data-type="guide-step" class="guide-step" guideid="430" stepid="0" stepnumber="1" guidename="[GP23] Justiciers et plus" label="[GP23] Justiciers et plus" baseurl="https://ganymede-dofus.com"><img src="https://ganymede-dofus.com/images/texteditor/guides.png" alt="GuideStep">[GP23] Justiciers et plus</span>&nbsp;de l''<span style="color: rgb(255, 255, 0);">étape 19</span>&nbsp;<span style="color: rgb(255, 255, 255);">jusqu''à l''</span><span style="color: rgb(255, 255, 0);">étape 30</span> incluse.</p></div></li></ul><p><span style="color: rgb(255, 255, 0);">Réalisez&nbsp;</span><span style="color: rgb(255, 255, 255);">la </span><span data-type="custom-tag" data-id="74" class="tag-dungeon" id="62" type="dungeon" name="Pyramide d''Ombre" imageurl="https://ganymede-dofus.com/images/icon_dungeon.png" dofusdbid="74"><img src="https://ganymede-dofus.com/images/icon_dungeon.png" alt="dungeon"><span>Pyramide d''Ombre</span></span>2️⃣ et</p><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p><span style="color: rgb(255, 255, 255);">Parlez </span>à <span style="color: rgb(255, 255, 0);">Ombre </span>à la <span style="color: rgb(98, 172, 255);">fin du donjon</span>&nbsp;<span style="color: rgb(255, 255, 255);">si vous faites le guide&nbsp;</span>(<span style="color: rgb(170, 71, 188);">Optionnel</span>).</p></div></li></ul><p><span style="color: rgb(5, 160, 69);">Astuces </span>:&nbsp;</p><p>1️⃣ Faites un <span style="color: rgb(255, 255, 0);">challenge&nbsp;</span>sur un <span data-type="custom-tag" data-id="4804" class="tag-monster" id="2381" type="monster" name="Viandargh" imageurl="https://api.dofusdb.fr/img/monsters/1566.png" dofusdbid="4804"><img src="https://api.dofusdb.fr/img/monsters/1566.png" alt="monster"><span>Viandargh</span></span>&nbsp;pour le succès monstre.</p><p>2️⃣ Faites un <span style="color: rgb(255, 255, 0);">challenge </span>sur un <span data-type="custom-tag" data-id="3570" class="tag-monster" id="1606" type="monster" name="Sombléro" imageurl="https://api.dofusdb.fr/img/monsters/1073.png" dofusdbid="3570"><img src="https://api.dofusdb.fr/img/monsters/1073.png" alt="monster"><span>Sombléro</span></span>&nbsp;pour le succès monstre.</p>', 48, '[GP48] NIMOTOPIA', NULL, '#8b5cf6', 0, 4480, false, '{}', 116, '2026-05-02 12:06:59.336', '2026-05-02 12:06:59.336');
INSERT INTO public."GuideMilestone" VALUES ('cmooaqrkr0081ygog0lqpzu1a', 'cmolc84qt0000noogp0gr4sjj', 'DONJON', 'Valonia 2.', NULL, '<p><span style="color: rgb(250, 0, 0);">Objectif :</span> Valonia 2.</p><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p><span style="color: rgb(255, 255, 0);">Commencez </span><span style="color: rgb(255, 255, 255);">et </span><span style="color: rgb(255, 255, 0);">terminez </span><span style="color: rgb(255, 255, 255);">le guide</span><span style="color: rgb(121, 134, 204);"> </span><span data-type="guide-step" class="guide-step" guideid="1140" stepid="0" stepnumber="1" guidename="[GP49] Valonia 2 : Ereboria" label="[GP49] Valonia 2 : Ereboria" baseurl="https://ganymede-dofus.com"><img src="https://ganymede-dofus.com/images/texteditor/guides.png" alt="GuideStep">[GP49] Valonia 2 : Ereboria</span>1️⃣2️⃣.</p></div></li></ul><p><span style="color: rgb(255, 255, 0);">Réalisez </span>le <span data-type="custom-tag" data-id="141" class="tag-dungeon" id="123" type="dungeon" name="Bastion des Marteaux-Aigris" imageurl="https://ganymede-dofus.com/images/icon_dungeon.png" dofusdbid="141"><img src="https://ganymede-dofus.com/images/icon_dungeon.png" alt="dungeon"><span>Bastion des Marteaux-Aigris</span></span>3️⃣.</p><p><span style="color: rgb(5, 160, 69);">Astuces :</span></p><p>1️⃣ Le c<span style="color: rgb(255, 255, 255);">ombat de l''</span><span style="color: rgb(255, 255, 0);">étape 6&nbsp;</span><span style="color: rgb(255, 255, 255);">peut vous demander </span><span style="color: rgb(255, 255, 0);">plusieurs tentatives</span><span style="color: rgb(255, 255, 255);">.</span></p><p>2️⃣&nbsp;A<span style="color: rgb(255, 255, 255);">près l''</span><span style="color: rgb(255, 255, 0);">étape 18</span>, <span style="color: rgb(255, 255, 0);">prévoyez </span>du <span style="color: rgb(255, 255, 0);">monde </span>pour les <span style="color: rgb(255, 255, 0);">combats </span>à <span style="color: rgb(255, 255, 0);">plusieurs</span>.</p><p><span style="color: rgb(255, 255, 255);">Si vous n''y arrivez pas, laissez de côté ce guide pour le moment, il vous sera rappelé de le terminer plus tard.</span></p><p>3️⃣ Faites un <span style="color: rgb(255, 255, 0);">challenge </span>sur un <span data-type="custom-tag" data-id="7218" class="tag-monster" id="4557" type="monster" name="Sanglirok" imageurl="https://api.dofusdb.fr/img/monsters/2330.png" dofusdbid="7218"><img src="https://api.dofusdb.fr/img/monsters/2330.png" alt="monster"><span>Sanglirok</span></span>&nbsp;pour le succès monstre.</p>', 49, '[GP49] Valonia 2 : Ereboria', NULL, '#8b5cf6', 220, 4640, false, '{}', 117, '2026-05-02 12:06:59.355', '2026-05-02 12:06:59.355');
INSERT INTO public."GuideMilestone" VALUES ('cmooaqrl10083ygogiymb9c6t', 'cmolc84qt0000noogp0gr4sjj', 'PREREQUIS', '👉 Étape bonus 👈', NULL, '<p style="text-align: center;"><span style="color: rgb(5, 160, 69);"><strong>👉 Étape bonus 👈</strong></span></p><p style="text-align: center;">🗡️ Mise à jour de l''équipement 🗡️</p><p>Selon votre <span style="color: rgb(255, 255, 0);">niveau </span>et vos <span style="color: rgb(255, 255, 0);">Kamas</span>, il <span style="color: rgb(255, 255, 0);">peut être intéressant </span>de prendre directement un <span style="color: rgb(255, 255, 0);">équipement 200</span>.</p><p><span style="color: rgb(255, 255, 0);">Sinon </span>choisissez un <span style="color: rgb(255, 255, 0);">équipement 199</span> sur le site : <a target="_blank" rel="noopener noreferrer nofollow" href="https://huzounet.fr/equipments">https://huzounet.fr/equipments</a>.1️⃣2️⃣</p><p style="text-align: left;">Dans les <span style="color: rgb(255, 255, 0);">filtres</span>, choisissez le <span style="color: rgb(255, 255, 0);">mode PVM</span>, votre <span style="color: rgb(255, 255, 0);">classe</span>, <span style="color: rgb(255, 255, 0);">niveau </span>et <span style="color: rgb(255, 255, 0);">élément</span>.</p><p><span style="color: rgb(5, 160, 69);">Astuces :</span></p><p>1️⃣ Vous êtes <span style="color: rgb(255, 255, 0);">libre </span>de <span style="color: rgb(255, 255, 0);">mettre </span>des <span style="color: rgb(255, 255, 0);">trophées </span>ou de prendre une <span style="color: rgb(255, 255, 0);">dragodinde</span>.</p><p>2️⃣&nbsp;<span style="color: rgb(255, 255, 255);">Prévoyez d''</span><span style="color: rgb(255, 255, 0);">FM</span><span style="color: rgb(255, 255, 255);"> vos </span><span style="color: rgb(255, 255, 0);">items </span><span style="color: rgb(255, 255, 255);">pour </span><span style="color: rgb(255, 255, 0);">augmenter votre vitalité maximale</span><span style="color: rgb(255, 255, 255);">.</span></p><p><span style="color: rgb(255, 255, 255);">Pensez à </span><span style="color: rgb(255, 255, 0);">FM </span><span style="color: rgb(255, 255, 255);">votre </span><span style="color: rgb(255, 255, 0);">arme </span><span style="color: rgb(255, 255, 255);">avec </span>une <span data-type="custom-tag" data-id="10057" class="tag-item" id="4249" type="item" name="Rune de chasse" imageurl="https://api.dofusdb.fr/img/items/78059.png" dofusdbid="10057"><img src="https://api.dofusdb.fr/img/items/78059.png" alt="item"><span>Rune de chasse</span></span> si vous êtes <span style="color: rgb(255, 255, 0);">chasseur</span>.</p>', 0, 'Introduction', NULL, '#a855f7', 440, 4640, true, '{}', 118, '2026-05-02 12:06:59.365', '2026-05-02 12:06:59.365');
INSERT INTO public."GuideMilestone" VALUES ('cmooaqrl60084ygogdhbadvyw', 'cmolc84qt0000noogp0gr4sjj', 'PREREQUIS', '👉 Étape bonus 👈', NULL, '<p style="text-align: center;"><span style="color: rgb(5, 160, 69);"><strong>👉 Étape bonus 👈</strong></span></p><p style="text-align: center;">🥩 Chasseur 190 à 200 🥩</p><p style="text-align: center;">🌽 Paysan/Alchimiste 170 à 180 🌽</p><p style="text-align: left;">Continuez de <span style="color: rgb(255, 255, 0);">monter </span>votre <span style="color: rgb(255, 255, 0);">métier </span>jusqu''au <span style="color: rgb(255, 255, 0);">niveau 180</span>.</p><p><span style="color: rgb(255, 255, 0);">Récupérez </span>du <span data-type="custom-tag" data-id="16454" class="tag-item" id="9451" type="item" name="Maïs" imageurl="https://api.dofusdb.fr/img/items/34554.png" dofusdbid="16454"><img src="https://api.dofusdb.fr/img/items/34554.png" alt="item"><span>Maïs</span></span> et/ou <span style="color: rgb(255, 255, 0);">fabriquez </span>des <span data-type="custom-tag" data-id="1737" class="tag-item" id="847" type="item" name="Pain des Champs" imageurl="https://api.dofusdb.fr/img/items/33068.png" dofusdbid="1737"><img src="https://api.dofusdb.fr/img/items/33068.png" alt="item"><span>Pain des Champs</span></span> si vous êtes <span style="color: rgb(255, 255, 0);">paysan</span>.</p><p style="text-align: left;"><span style="color: rgb(255, 255, 0);">Récupérez </span>des <span data-type="custom-tag" data-id="16387" class="tag-item" id="9415" type="item" name="Belladone" imageurl="https://api.dofusdb.fr/img/items/35638.png" dofusdbid="16387"><img src="https://api.dofusdb.fr/img/items/35638.png" alt="item"><span>Belladone</span></span> et/ou <span style="color: rgb(255, 255, 0);">fabriquez </span>des <span data-type="custom-tag" data-id="16722" class="tag-item" id="9588" type="item" name="Potion Axel Raide" imageurl="https://api.dofusdb.fr/img/items/12769.png" dofusdbid="16722"><img src="https://api.dofusdb.fr/img/items/12769.png" alt="item"><span>Potion Axel Raide</span></span> si vous êtes <span style="color: rgb(255, 255, 0);">alchimiste</span>.</p><p style="text-align: center;">🥩 Chasseur 190 à 200 🥩</p><p>Pour monter le métier <span style="color: rgb(255, 255, 0);">chasseur niveau 200</span>, prévoyez :</p><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p>158&nbsp;<span data-type="custom-tag" data-id="17158" class="tag-item" id="9994" type="item" name="Viande Noire" imageurl="https://api.dofusdb.fr/img/items/63439.png" dofusdbid="17158"><img src="https://api.dofusdb.fr/img/items/63439.png" alt="item"><span>Viande Noire</span></span>.</p></div></li><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p>316&nbsp;<span data-type="custom-tag" data-id="16454" class="tag-item" id="9451" type="item" name="Maïs" imageurl="https://api.dofusdb.fr/img/items/34554.png" dofusdbid="16454"><img src="https://api.dofusdb.fr/img/items/34554.png" alt="item"><span>Maïs</span></span>.</p></div></li><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p>158&nbsp;<span data-type="custom-tag" data-id="1985" class="tag-item" id="990" type="item" name="Résine" imageurl="https://api.dofusdb.fr/img/items/15382.png" dofusdbid="1985"><img src="https://api.dofusdb.fr/img/items/15382.png" alt="item"><span>Résine</span></span>&nbsp;(ou 16&nbsp;<span data-type="custom-tag" data-id="16835" class="tag-item" id="9700" type="item" name="Sachet de Résine" imageurl="https://api.dofusdb.fr/img/items/180014.png" dofusdbid="16835"><img src="https://api.dofusdb.fr/img/items/180014.png" alt="item"><span>Sachet de Résine</span></span>)</p></div></li></ul><p>Ensuite <span style="color: rgb(255, 255, 0);">fabriquez </span>des <span data-type="custom-tag" data-id="17203" class="tag-item" id="10039" type="item" name="Andouillette de Gibier" imageurl="https://api.dofusdb.fr/img/items/69771.png" dofusdbid="17203"><img src="https://api.dofusdb.fr/img/items/69771.png" alt="item"><span>Andouillette de Gibier</span></span><span style="color: rgb(255, 255, 255);">.</span></p><p><span style="color: rgb(250, 0, 0);">Féliciations ! </span><span style="color: rgb(255, 255, 255);">Vous êtes </span><span style="color: rgb(255, 255, 0);">chasseur 2001️⃣</span><span style="color: rgb(255, 255, 255);">.</span></p><p><span style="color: rgb(5, 160, 69);">Astuce :</span></p><p>1️⃣ Dorénavant vous pouvez <span style="color: rgb(255, 255, 0);">drop&nbsp;</span>des<span style="color: rgb(255, 255, 255);"> </span><span data-type="custom-tag" data-id="17161" class="tag-item" id="9997" type="item" name="Bidoche Goûtue" imageurl="https://api.dofusdb.fr/img/items/63448.png" dofusdbid="17161"><img src="https://api.dofusdb.fr/img/items/63448.png" alt="item"><span>Bidoche Goûtue</span></span>&nbsp;sur les <span style="color: rgb(255, 255, 0);">boss 200</span>.</p><p><span style="color: rgb(255, 255, 0);">Gardez en 2</span>&nbsp;par personnage pour le guide&nbsp;<span data-type="guide-step" class="guide-step" guideid="704" stepid="0" stepnumber="1" guidename="[GP67] Dofus Vulbis" label="[GP67] Dofus Vulbis" baseurl="https://ganymede-app.com"><img src="https://ganymede-app.com/images/texteditor/guides.png" alt="GuideStep">[GP67] Dofus Vulbis</span>.</p>', 67, '[GP67] Dofus Vulbis', NULL, '#a855f7', 660, 4640, true, '{}', 119, '2026-05-02 12:06:59.37', '2026-05-02 12:06:59.37');
INSERT INTO public."GuideMilestone" VALUES ('cmooaqrli0086ygogdp55j11r', 'cmolc84qt0000noogp0gr4sjj', 'DOFUS', 'Eliocalypse Résonance', NULL, '<p style="text-align: left;"><span style="color: rgb(250, 0, 0);">Objectifs :</span> <span data-type="custom-tag" data-id="6980" class="tag-item" id="2015" type="item" name="Dofus Vulbis" imageurl="https://api.dofusdb.fr/img/items/23004.png" dofusdbid="6980"><img src="https://api.dofusdb.fr/img/items/23004.png" alt="item"><span>Dofus Vulbis</span></span>&nbsp;et Eliocalypse.</p><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p><span style="color: rgb(255, 255, 0);">Commencez </span><span style="color: rgb(255, 255, 255);">le guide </span><span data-type="guide-step" class="guide-step" guideid="1714" stepid="0" stepnumber="1" guidename="[GP66] Eliocalypse Résonance" label="[GP66] Eliocalypse Résonance" baseurl="https://ganymede-dofus.com"><img src="https://ganymede-dofus.com/images/texteditor/guides.png" alt="GuideStep">[GP66] Eliocalypse Résonance</span> jusqu''à l''<span style="color: rgb(255, 255, 0);">étape 26</span> incluse.</p></div></li></ul><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p><span style="color: rgb(255, 255, 0);">Commencez </span>le guide&nbsp;<span data-type="guide-step" class="guide-step" guideid="704" stepid="0" stepnumber="1" guidename="[GP67] Dofus Vulbis" label="[GP67] Dofus Vulbis" baseurl="https://ganymede-dofus.com"><img src="https://ganymede-dofus.com/images/texteditor/guides.png" alt="GuideStep">[GP67] Dofus Vulbis</span>1️⃣<span style="color: rgb(121, 134, 204);"> </span><span style="color: rgb(255, 255, 255);">jusqu''à l''</span><span style="color: rgb(255, 255, 0);">étape 10</span> incluse&nbsp;<span style="color: rgb(255, 255, 255);">pour débloquer le drop du&nbsp;</span><span data-type="custom-tag" data-id="21189" class="tag-item" id="13404" type="item" name="Parangon de puissance" imageurl="https://api.dofusdb.fr/img/items/50733.png" dofusdbid="21189"><img src="https://api.dofusdb.fr/img/items/50733.png" alt="item"><span>Parangon de puissance</span></span>.</p></div></li></ul><p><span style="color: rgb(5, 160, 69);">Astuces :</span></p><p>1️⃣&nbsp;Il est important de faire cette partie car <span style="color: rgb(255, 255, 0);">chaque boss 200</span> vous donne une <span style="color: rgb(255, 255, 0);">faible&nbsp;chance </span>de <span style="color: rgb(255, 255, 0);">drop </span>le <span data-type="custom-tag" data-id="21189" class="tag-item" id="13404" type="item" name="Parangon de puissance" imageurl="https://api.dofusdb.fr/img/items/50733.png" dofusdbid="21189"><img src="https://api.dofusdb.fr/img/items/50733.png" alt="item"><span>Parangon de puissance</span></span>.</p><p>Une fois devant un boss, <span style="color: rgb(255, 255, 0);">maximisez </span>vos <span style="color: rgb(255, 255, 0);">chances </span>en faisant un <span style="color: rgb(255, 255, 0);">maximum </span>de <span style="color: rgb(255, 255, 0);">challenge</span> et prévoyez de la <span style="color: rgb(255, 255, 0);">prospection</span>.</p><p>Pour des <span style="color: rgb(255, 255, 0);">équipements 200&nbsp;</span>avec de la <span style="color: rgb(255, 255, 0);">prospection </span>et des <span style="color: rgb(255, 255, 0);">dégâts</span>, allez sur ce site : <a target="_blank" rel="noopener noreferrer nofollow" href="https://huzounet.fr">https://huzounet.fr</a>&nbsp;et mettez le <span style="color: rgb(255, 255, 0);">filtre prospection</span>.</p>', 66, '[GP66] Eliocalypse Résonance', NULL, '#f59e0b', 0, 4640, false, '{}', 120, '2026-05-02 12:06:59.383', '2026-05-02 12:06:59.383');
