INSERT INTO public."GuideMilestone" VALUES ('cmooaqrrb0097ygog2t8ix3d1', 'cmolc84qt0000noogp0gr4sjj', 'DOFUS', 'Xélorium 3 et Prérequis du', NULL, '<p><span style="color: rgb(250, 0, 0);">Objectifs :</span> Xélorium 3 et Prérequis du <span data-type="custom-tag" data-id="19398" class="tag-item" id="11799" type="item" name="Dofus Forgelave" imageurl="https://api.dofusdb.fr/img/items/23024.png" dofusdbid="19398"><img src="https://api.dofusdb.fr/img/items/23024.png" alt="item"><span>Dofus Forgelave</span></span> et du <span data-type="custom-tag" data-id="26066" class="tag-item" id="16395" type="item" name="Dofus du Cauchemar" imageurl="https://api.dofusdb.fr/img/items/23034.png" dofusdbid="26066"><img src="https://api.dofusdb.fr/img/items/23034.png" alt="item"><span>Dofus du Cauchemar</span></span>.</p><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p><span style="color: rgb(255, 255, 0);">Commencez </span>et <span style="color: rgb(255, 255, 0);">terminez </span>le guide&nbsp;<span data-type="guide-step" class="guide-step" guideid="479" stepid="0" stepnumber="1" guidename="[GP58] Xélorium 3" label="[GP58] Xélorium 3" baseurl="https://ganymede-dofus.com"><img src="https://ganymede-dofus.com/images/texteditor/guides.png" alt="GuideStep">[GP58] Xélorium 3</span>.</p></div></li></ul><p><span style="color: rgb(255, 255, 0);">Réalisez </span><span style="color: rgb(255, 255, 255);">l''<span data-type="custom-tag" data-id="87" class="tag-dungeon" id="74" type="dungeon" name="Œil de Vortex" imageurl="https://ganymede-dofus.com/images/icon_dungeon.png" dofusdbid="87"><img src="https://ganymede-dofus.com/images/icon_dungeon.png" alt="dungeon"><span>Œil de Vortex</span></span>&nbsp;et&nbsp;</span></p><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p>A l''<span style="color: rgb(255, 255, 0);">étape 70</span>, suivez bien ce qu''il faut faire à la <span style="color: rgb(98, 172, 255);">fin du donjon</span>.</p></div></li></ul><ul data-type="taskList"><li data-checked="false" data-type="taskItem"><label><span></span></label><div><p><span style="color: rgb(255, 255, 0);">Terminez </span>le guide <span data-type="guide-step" class="guide-step" guideid="427" stepid="0" stepnumber="1" guidename="[GP59] La Fratrie des Oubliés" label="[GP59] La Fratrie des Oubliés" baseurl="https://ganymede-dofus.com"><img src="https://ganymede-dofus.com/images/texteditor/guides.png" alt="GuideStep">[GP59] La Fratrie des Oubliés</span> depuis l''<span style="color: rgb(255, 255, 0);">étape 49</span> en lançant la quête le <span data-type="custom-tag" data-id="1934" class="tag-quest" id="1628" type="quest" name="Le gang des Toxines" imageurl="https://ganymede-dofus.com/images/icon_quest.png" dofusdbid="1934"><img src="https://ganymede-dofus.com/images/icon_quest.png" alt="quest"><span>Le gang des Toxines</span></span>.</p></div></li></ul><p><span style="color: rgb(5, 160, 69);">Astuce </span>:&nbsp;</p><p>1️⃣ <span style="color: rgb(255, 255, 255);">Faites un </span><span style="color: rgb(255, 255, 0);">challenge </span><span style="color: rgb(255, 255, 255);">contre le&nbsp;</span><span data-type="custom-tag" data-id="3835" class="tag-monster" id="1848" type="monster" name="Vortex" imageurl="https://api.dofusdb.fr/img/monsters/1208.png" dofusdbid="3835"><img src="https://api.dofusdb.fr/img/monsters/1208.png" alt="monster"><span>Vortex</span></span>&nbsp;pour le succès monstre.</p>', 58, '[GP58] Xélorium 3', NULL, '#f59e0b', 440, 5280, false, '{}', 134, '2026-05-02 12:06:59.591', '2026-05-02 12:06:59.591');
INSERT INTO public."GuideMilestone" VALUES ('cmooaqrrt009aygogiu3wwpsb', 'cmolc84qt0000noogp0gr4sjj', 'PREREQUIS', '👉 Étape bonus 👈', NULL, '<p style="text-align: center;"><span style="color: rgb(5, 160, 69);"><strong>👉 Étape bonus 👈</strong></span></p><p style="text-align: center;">🌽 Paysan 190 à 200 🌽</p><p style="text-align: left;">Continuez de <span style="color: rgb(255, 255, 0);">monter </span>votre <span style="color: rgb(255, 255, 0);">métier </span>jusqu''au <span style="color: rgb(255, 255, 0);">niveau 200</span>.</p><p><span style="color: rgb(255, 255, 0);">Récupérez </span>du <span data-type="custom-tag" data-id="16456" class="tag-item" id="9453" type="item" name="Millet" imageurl="https://api.dofusdb.fr/img/items/34555.png" dofusdbid="16456"><img src="https://api.dofusdb.fr/img/items/34555.png" alt="item"><span>Millet</span></span> et/ou <span style="color: rgb(255, 255, 0);">fabriquez </span>des <span data-type="custom-tag" data-id="743" class="tag-item" id="347" type="item" name="Brioche Dorée" imageurl="https://api.dofusdb.fr/img/items/33008.png" dofusdbid="743"><img src="https://api.dofusdb.fr/img/items/33008.png" alt="item"><span>Brioche Dorée</span></span> si vous êtes <span style="color: rgb(255, 255, 0);">paysan</span>.</p><p style="text-align: left;"><span style="color: rgb(255, 255, 0);">Récupérez </span>des <span data-type="custom-tag" data-id="16389" class="tag-item" id="9417" type="item" name="Mandragore" imageurl="https://api.dofusdb.fr/img/items/36645.png" dofusdbid="16389"><img src="https://api.dofusdb.fr/img/items/36645.png" alt="item"><span>Mandragore</span></span> et/ou <span style="color: rgb(255, 255, 0);">fabriquez </span>des <span data-type="custom-tag" data-id="11506" class="tag-item" id="5284" type="item" name="Potion Raide Rêve" imageurl="https://api.dofusdb.fr/img/items/12721.png" dofusdbid="11506"><img src="https://api.dofusdb.fr/img/items/12721.png" alt="item"><span>Potion Raide Rêve</span></span> si vous êtes <span style="color: rgb(255, 255, 0);">alchimiste</span>.</p><p style="text-align: left;"><span style="color: rgb(216, 27, 67);">Félicitations!</span> Vous êtes <span style="color: rgb(255, 255, 0);">Paysan</span> et/ou <span style="color: rgb(255, 255, 0);">Alchimiste 200</span> !</p>', 0, 'Introduction', NULL, '#a855f7', 660, 5280, true, '{}', 135, '2026-05-02 12:06:59.609', '2026-05-02 12:06:59.609');
